  /** Trade · Convert tab — RFQ layout; reuses plan-detail amount row styling. */
  const initTradeConvertPage = () => {
    const root = document.querySelector("[data-trade-convert-root]");
    const payInp = root?.querySelector("[data-trade-convert-pay-input]");
    const recvInp = root?.querySelector("[data-trade-convert-recv-input]");
    if (!root || !payInp || !recvInp) return;

    const pairFromEl = root.querySelector("[data-trade-convert-pair-from]");
    const pairToEl = root.querySelector("[data-trade-convert-pair-to]");
    const rateEl = root.querySelector("[data-trade-convert-rate]");
    const payAvailEl = root.querySelector("[data-trade-convert-pay-avail]");
    const recvAvailEl = root.querySelector("[data-trade-convert-recv-avail]");
    const payIcon = root.querySelector("[data-trade-convert-pay-icon]");
    const recvIcon = root.querySelector("[data-trade-convert-recv-icon]");
    const payCurEl = root.querySelector("[data-trade-convert-pay-currency]");
    const recvCurEl = root.querySelector("[data-trade-convert-recv-currency]");
    const maxBtn = root.querySelector("[data-trade-convert-max]");
    const swapBtn = root.querySelector("[data-trade-convert-swap]");
    const previewBtn = root.querySelector("[data-trade-convert-preview]");

    const readRate = () => {
      const n = parseFloat(String(root.getAttribute("data-convert-rate") || ""));
      return Number.isFinite(n) && n > 0 ? n : 2438104.61;
    };

    let rateTwdPerBtc = readRate();
    let payCurrency = "TWD";
    let receiveCurrency = "BTC";

    const availForCurrency = (code) => {
      const c = String(code || "").toUpperCase();
      const n = Number(PROTOTYPE_BALANCES[c]);
      return Number.isFinite(n) && n >= 0 ? n : 0;
    };

    let availPay = availForCurrency(payCurrency);
    let availReceive = availForCurrency(receiveCurrency);

    /** Max value for either amount field on the convert form. */
    const CONVERT_AMOUNT_MAX = 999999.99;

    const CONVERT_BTC_DECIMALS = 6;
    const roundConvertBtc = (n) => {
      if (!Number.isFinite(n)) return NaN;
      const f = 10 ** CONVERT_BTC_DECIMALS;
      return Math.round(n * f) / f;
    };

    const fmtConvertBtc = (n) => {
      if (!Number.isFinite(n) || n < 0) return "";
      return roundConvertBtc(n).toFixed(CONVERT_BTC_DECIMALS);
    };

    const CONVERT_FIAT_DECIMALS = 2;
    const roundConvertFiat = (n) => {
      if (!Number.isFinite(n)) return NaN;
      const f = 10 ** CONVERT_FIAT_DECIMALS;
      return Math.round(n * f) / f;
    };

    const iconFor = (code) => {
      if (code === "BTC") return "assets/icon_currency_btc.svg";
      if (code === "TWD") return "assets/icon_currency_TWD.svg";
      return "assets/icon_currency_usdt.svg";
    };

    const fmtTwd = (n) =>
      new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(
        Math.round(n),
      );

    const fmtBtcAvail = (n) =>
      Number.isFinite(n)
        ? roundConvertBtc(n).toFixed(CONVERT_BTC_DECIMALS)
        : "0." + "0".repeat(CONVERT_BTC_DECIMALS);

    /** TWD (and other fiat on this screen) — up to 2 decimals so cap 999,999.99 renders correctly. */
    const fmtConvertFiat = (n) =>
      new Intl.NumberFormat("en-US", {
        minimumFractionDigits: 0,
        maximumFractionDigits: 2,
      }).format(Number.isFinite(n) ? n : 0);

    const parsePay = () => {
      const raw = String(payInp.value || "").replace(/,/g, "").trim();
      const x = parseFloat(raw);
      if (!Number.isFinite(x)) return NaN;
      if (payCurrency === "BTC") return roundConvertBtc(x);
      if (payCurrency === "TWD") return roundConvertFiat(x);
      return x;
    };

    const formatPayField = (n) => {
      if (!Number.isFinite(n) || n < 0) return "";
      if (payCurrency === "TWD")
        return fmtConvertFiat(roundConvertFiat(n));
      return fmtConvertBtc(n);
    };

    const formatReceiveField = (n) => {
      if (!Number.isFinite(n) || n < 0) return "";
      if (receiveCurrency === "BTC") return fmtConvertBtc(n);
      if (receiveCurrency === "TWD")
        return fmtConvertFiat(roundConvertFiat(n));
      return fmtConvertFiat(n);
    };

    const parseRecv = () => {
      const raw = String(recvInp.value || "").replace(/,/g, "").trim();
      const x = parseFloat(raw);
      if (!Number.isFinite(x)) return NaN;
      if (receiveCurrency === "BTC") return roundConvertBtc(x);
      if (receiveCurrency === "TWD") return roundConvertFiat(x);
      return x;
    };

    const convertForward = (payAmt) => {
      if (!Number.isFinite(payAmt) || payAmt <= 0) return NaN;
      if (payCurrency === "TWD" && receiveCurrency === "BTC")
        return payAmt / rateTwdPerBtc;
      if (payCurrency === "BTC" && receiveCurrency === "TWD")
        return payAmt * rateTwdPerBtc;
      return NaN;
    };

    const convertFromReceive = (recvAmt) => {
      if (!Number.isFinite(recvAmt) || recvAmt <= 0) return NaN;
      if (payCurrency === "TWD" && receiveCurrency === "BTC")
        return recvAmt * rateTwdPerBtc;
      if (payCurrency === "BTC" && receiveCurrency === "TWD")
        return recvAmt / rateTwdPerBtc;
      return NaN;
    };

    const CONVERT_PLACEHOLDER_BTC = "0";
    const CONVERT_PLACEHOLDER_TWD = "0";
    const CONVERT_TWD_AMOUNT_HINT = "≈ Min 50\nMax 100K";

    const renderAmountPlaceholders = () => {
      const ph = (code) =>
        code === "BTC" ? CONVERT_PLACEHOLDER_BTC : CONVERT_PLACEHOLDER_TWD;
      if (payInp) payInp.placeholder = ph(payCurrency);
      if (recvInp) recvInp.placeholder = ph(receiveCurrency);
    };

    const payHintEl = root.querySelector("[data-trade-convert-pay-hint]");
    const recvHintEl = root.querySelector("[data-trade-convert-recv-hint]");

    const syncTwdAmountHints = () => {
      const empty = (inp) => !String(inp?.value || "").trim();
      if (payHintEl) {
        const show = payCurrency === "TWD" && empty(payInp);
        payHintEl.hidden = !show;
        if (show) payHintEl.textContent = CONVERT_TWD_AMOUNT_HINT;
      }
      if (recvHintEl) {
        const show = receiveCurrency === "TWD" && empty(recvInp);
        recvHintEl.hidden = !show;
        if (show) recvHintEl.textContent = CONVERT_TWD_AMOUNT_HINT;
      }
    };

    const syncConvertPreviewCta = () => {
      if (!previewBtn) return;
      const pay = parsePay();
      const recv = parseRecv();
      const ok =
        Number.isFinite(pay) &&
        pay > 0 &&
        Number.isFinite(recv) &&
        recv > 0;
      previewBtn.disabled = !ok;
      document.dispatchEvent(
        new CustomEvent("convert-preview-state-changed", {
          detail: { disabled: previewBtn.disabled },
        }),
      );
    };

    const syncReceiveFromPay = () => {
      try {
        let payAmt = parsePay();
        if (!Number.isFinite(payAmt) || payAmt <= 0) {
          recvInp.value = "";
          return;
        }
        if (payAmt > CONVERT_AMOUNT_MAX) {
          payAmt = CONVERT_AMOUNT_MAX;
          payInp.value = formatPayField(payAmt);
        }
        if (payCurrency === "BTC") {
          payAmt = roundConvertBtc(payAmt);
          payInp.value = formatPayField(payAmt);
        } else if (payCurrency === "TWD") {
          payAmt = roundConvertFiat(payAmt);
          payInp.value = formatPayField(payAmt);
        }
        let out = convertForward(payAmt);
        if (!Number.isFinite(out)) {
          recvInp.value = "";
          return;
        }
        if (out > CONVERT_AMOUNT_MAX) {
          recvInp.value = formatReceiveField(CONVERT_AMOUNT_MAX);
          const payIdeal = convertFromReceive(CONVERT_AMOUNT_MAX);
          if (!Number.isFinite(payIdeal) || payIdeal <= 0) return;
          if (payIdeal > CONVERT_AMOUNT_MAX) {
            payInp.value = formatPayField(CONVERT_AMOUNT_MAX);
            const outCapped = convertForward(CONVERT_AMOUNT_MAX);
            recvInp.value = Number.isFinite(outCapped)
              ? formatReceiveField(outCapped)
              : formatReceiveField(CONVERT_AMOUNT_MAX);
          } else {
            payInp.value = formatPayField(payIdeal);
          }
          return;
        }
        if (receiveCurrency === "BTC") out = roundConvertBtc(out);
        else if (receiveCurrency === "TWD") out = roundConvertFiat(out);
        recvInp.value = formatReceiveField(out);
      } finally {
        syncTwdAmountHints();
        syncConvertPreviewCta();
      }
    };

    const syncPayFromReceive = () => {
      try {
        let recvAmt = parseRecv();
        if (!Number.isFinite(recvAmt) || recvAmt <= 0) {
          payInp.value = "";
          return;
        }
        if (recvAmt > CONVERT_AMOUNT_MAX) {
          recvAmt = CONVERT_AMOUNT_MAX;
          recvInp.value = formatReceiveField(recvAmt);
        }
        if (receiveCurrency === "BTC") {
          recvAmt = roundConvertBtc(recvAmt);
          recvInp.value = formatReceiveField(recvAmt);
        } else if (receiveCurrency === "TWD") {
          recvAmt = roundConvertFiat(recvAmt);
          recvInp.value = formatReceiveField(recvAmt);
        }
        let pay = convertFromReceive(recvAmt);
        if (!Number.isFinite(pay)) {
          payInp.value = "";
          return;
        }
        if (pay > CONVERT_AMOUNT_MAX) {
          payInp.value = formatPayField(CONVERT_AMOUNT_MAX);
          const outCapped = convertForward(CONVERT_AMOUNT_MAX);
          recvInp.value = Number.isFinite(outCapped)
            ? formatReceiveField(outCapped)
            : formatReceiveField(CONVERT_AMOUNT_MAX);
          return;
        }
        payInp.value = formatPayField(pay);
      } finally {
        syncTwdAmountHints();
        syncConvertPreviewCta();
      }
    };

    const renderAvails = () => {
      if (payAvailEl) {
        const a =
          payCurrency === "BTC"
            ? fmtBtcAvail(availPay)
            : fmtConvertFiat(roundConvertFiat(availPay));
        payAvailEl.textContent = `Avail. ${a} ${payCurrency}`;
      }
      if (recvAvailEl) {
        const a =
          receiveCurrency === "BTC"
            ? fmtBtcAvail(availReceive)
            : fmtConvertFiat(roundConvertFiat(availReceive));
        recvAvailEl.textContent = `Avail. ${a} ${receiveCurrency}`;
      }
    };

    const renderRate = () => {
      if (!rateEl) return;
      rateEl.textContent = `1 BTC = ${fmtTwd(rateTwdPerBtc)} TWD`;
    };

    const renderPair = () => {
      if (pairFromEl) pairFromEl.textContent = payCurrency;
      if (pairToEl) pairToEl.textContent = receiveCurrency;
    };

    const renderIcons = () => {
      if (payIcon) payIcon.src = iconFor(payCurrency);
      if (recvIcon) recvIcon.src = iconFor(receiveCurrency);
      if (payCurEl) payCurEl.textContent = payCurrency;
      if (recvCurEl) recvCurEl.textContent = receiveCurrency;
    };

    const payCurBtn = root.querySelector("[data-trade-convert-pay-currency-btn]");
    const recvCurBtn = root.querySelector("[data-trade-convert-recv-currency-btn]");
    const phoneContainer = document.querySelector(".phone-container");
    let convertSnackbarTimeout = null;

    const showConvertSnackbar = (message) => {
      const snackbar = phoneContainer?.querySelector("[data-snackbar]");
      if (!snackbar) return;
      const text = snackbar.querySelector("[data-snackbar-text]");
      if (text) text.textContent = message;
      if (convertSnackbarTimeout) {
        clearTimeout(convertSnackbarTimeout);
        convertSnackbarTimeout = null;
      }
      snackbar.hidden = false;
      snackbar.classList.remove("is-visible");
      void snackbar.offsetWidth;
      requestAnimationFrame(() => snackbar.classList.add("is-visible"));
      convertSnackbarTimeout = setTimeout(() => {
        snackbar.classList.remove("is-visible");
        convertSnackbarTimeout = setTimeout(() => {
          if (!snackbar.classList.contains("is-visible")) snackbar.hidden = true;
        }, 320);
      }, 2200);
    };

    const showConvertNotInPrototype = () =>
      showConvertSnackbar("Not in prototype");

    [payCurBtn, recvCurBtn].forEach((btn) => {
      btn?.addEventListener("click", (e) => {
        e.stopPropagation();
        showConvertNotInPrototype();
      });
    });

    payInp.addEventListener("input", syncReceiveFromPay);
    recvInp.addEventListener("input", syncPayFromReceive);

    const payAmountRow = payInp.closest(".plan-detail-panel__amount-row");
    const recvAmountRow = recvInp.closest(".plan-detail-panel__amount-row");
    const payFieldLabel = payAmountRow
      ?.closest(".trade-convert-page__field")
      ?.querySelector(".plan-detail-panel__section-label");
    const scrollConvertContentTo = (el, topOffsetPx = 24) => {
      const scroller = document.querySelector("[data-content]");
      if (!scroller || !el) return;
      const sr = scroller.getBoundingClientRect();
      const er = el.getBoundingClientRect();
      const nextTop = scroller.scrollTop + (er.top - sr.top) - topOffsetPx;
      scroller.scrollTo({ top: Math.max(0, nextTop), behavior: "smooth" });
    };
    const bindConvertAmountRowFocus = (row, inp) => {
      if (!row || !inp) return;
      row.addEventListener("click", (e) => {
        if (e.target.closest(".plan-detail-panel__currency-pill")) return;
        if (e.target.closest("input")) return;
        inp.focus();
        document.dispatchEvent(new CustomEvent("fake-keyboard-show"));
      });
    };
    bindConvertAmountRowFocus(payAmountRow, payInp);
    bindConvertAmountRowFocus(recvAmountRow, recvInp);

    payInp.addEventListener("focus", () => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-show"));
      requestAnimationFrame(() => {
        requestAnimationFrame(() => scrollConvertContentTo(payFieldLabel));
      });
    });

    recvInp.addEventListener("focus", () => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-show"));
      requestAnimationFrame(() => {
        requestAnimationFrame(() => scrollConvertContentTo(payFieldLabel));
      });
    });

    const bindKeyboardGestureFocus = (inp, triggerEl) => {
      if (!inp || !triggerEl) return;
      const LONG_PRESS_MS = 320;
      let holdTimer = null;
      let longPressTriggered = false;

      const showFakeKeyboard = () => {
        inp.focus();
        // Ensure the desktop fake keyboard can be re-shown even if this field is already focused.
        document.dispatchEvent(new CustomEvent("fake-keyboard-show"));
      };

      triggerEl.addEventListener("dblclick", () => {
        showFakeKeyboard();
      });

      triggerEl.addEventListener("pointerdown", (e) => {
        if (e.target.closest(".plan-detail-panel__currency-pill")) return;
        longPressTriggered = false;
        if (holdTimer) clearTimeout(holdTimer);
        holdTimer = setTimeout(() => {
          longPressTriggered = true;
          showFakeKeyboard();
        }, LONG_PRESS_MS);
      });

      const clearHold = () => {
        if (holdTimer) {
          clearTimeout(holdTimer);
          holdTimer = null;
        }
      };

      triggerEl.addEventListener("pointerup", clearHold);
      triggerEl.addEventListener("pointerleave", clearHold);
      triggerEl.addEventListener("pointercancel", clearHold);
      triggerEl.addEventListener("contextmenu", (e) => {
        if (!longPressTriggered) return;
        e.preventDefault();
      });
    };
    bindKeyboardGestureFocus(payInp, payAmountRow || payInp);
    bindKeyboardGestureFocus(recvInp, recvAmountRow || recvInp);

    if (maxBtn) {
      maxBtn.addEventListener("click", () => {
        const capped = Math.min(availPay, CONVERT_AMOUNT_MAX);
        payInp.value = formatPayField(capped);
        syncReceiveFromPay();
      });
    }

    swapBtn?.addEventListener("click", () => {
      const pc = payCurrency;
      payCurrency = receiveCurrency;
      receiveCurrency = pc;
      availPay = availForCurrency(payCurrency);
      availReceive = availForCurrency(receiveCurrency);
      const pv = payInp.value;
      payInp.value = recvInp.value;
      recvInp.value = pv;
      renderPair();
      renderIcons();
      renderAmountPlaceholders();
      renderAvails();
      syncReceiveFromPay();
    });

    rateTwdPerBtc = readRate();
    renderPair();
    renderIcons();
    renderAmountPlaceholders();
    renderRate();
    renderAvails();

    const resetConvertAmountsToEmpty = () => {
      payInp.value = "";
      recvInp.value = "";
      syncReceiveFromPay();
    };

    resetConvertAmountsToEmpty();

    document.addEventListener("trade-page-changed", (e) => {
      if (e?.detail?.pageId === "convert") resetConvertAmountsToEmpty();
    });
  };

  /** Trade · Convert — rate row + confirm price info open the fee explainer bottom sheet. */
  const initTradeConvertRatePanel = () => {
    if (initTradeConvertRatePanel._inited) return;
    const rateInfoSheet = document.querySelector(
      "[data-trade-convert-rate-info-sheet]",
    );
    const rateInfoPanel = rateInfoSheet?.querySelector(".currency-sheet__panel");
    const confirmSheet = document.querySelector("[data-trade-convert-confirm-sheet]");
    const confirmPanel = confirmSheet?.querySelector(".currency-sheet__panel");
    const rateRowOpenBtn = document.querySelector("[data-trade-convert-rate-open]");
    const rateInfoOpenBtn = document.querySelector(
      "[data-trade-convert-rate-info-open]",
    );
    if (!rateInfoSheet || !rateInfoPanel) return;
    initTradeConvertRatePanel._inited = true;

    const FEE_PCT = 0.001;
    const feePctLabel = (FEE_PCT * 100).toFixed(1);

    const roundBtc = (n) => {
      if (!Number.isFinite(n)) return NaN;
      return Math.round(n * 1e6) / 1e6;
    };

    const roundFiat = (n) => {
      if (!Number.isFinite(n)) return NaN;
      return Math.round(n * 1e2) / 1e2;
    };

    const fmtFiatFull = (n) =>
      new Intl.NumberFormat("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(Number.isFinite(n) ? n : 0);

    const fmtBtc = (n) =>
      Number.isFinite(n) ? roundBtc(n).toFixed(6) : "0.000000";

    const parsePayAmount = () => {
      const root = document.querySelector("[data-trade-convert-root]");
      const payInp = root?.querySelector("[data-trade-convert-pay-input]");
      const payCode =
        root
          ?.querySelector("[data-trade-convert-pay-currency]")
          ?.textContent?.trim() || "TWD";
      const x = parseFloat(String(payInp?.value || "").replace(/,/g, "").trim());
      if (!Number.isFinite(x) || x <= 0) return { payCode, payAmt: NaN };
      return {
        payCode,
        payAmt: payCode === "BTC" ? roundBtc(x) : roundFiat(x),
      };
    };

    const syncRateInfoDesc = () => {
      const descEl = rateInfoSheet.querySelector(
        "[data-trade-convert-rate-info-desc]",
      );
      if (!descEl) return;
      const { payCode, payAmt } = parsePayAmount();
      let fee = Number.isFinite(payAmt) ? payAmt * FEE_PCT : 0;
      if (payCode === "BTC") fee = roundBtc(fee);
      else fee = roundFiat(fee);
      const feeLabel =
        payCode === "BTC"
          ? `${fmtBtc(fee)} ${payCode}`
          : `${fmtFiatFull(fee)} ${payCode}`;
      descEl.textContent = `A ${feePctLabel}% fee (${feeLabel}) is already included in your conversion price. No extra fees apply.`;
    };

    const openRateInfoSheet = (openedFrom) => {
      syncRateInfoDesc();
      rateInfoSheet.dataset.openedFrom = openedFrom;
      sheetOpenWithInstantBackdrop(rateInfoSheet);
    };

    const openFromConfirm = () => {
      syncRateInfoDesc();
      rateInfoSheet.dataset.openedFrom = "confirm";
      if (getBottomSheetStacking()) {
        sheetOpenWithInstantBackdrop(rateInfoSheet);
        return;
      }
      sheetCloseWithBackdropHandoff(
        confirmSheet,
        confirmPanel,
        () => {
          sheetOpenWithInstantBackdrop(rateInfoSheet);
        },
        { suppressNestedScrim: true },
      );
    };

    const closeRateInfoSheet = () => {
      const openedFrom = rateInfoSheet.dataset.openedFrom || "";
      if (getBottomSheetStacking() || openedFrom !== "confirm") {
        sheetCloseWithBackdropHandoff(rateInfoSheet, rateInfoPanel, null, {
          suppressNestedScrim: true,
        });
        return;
      }
      sheetCloseWithBackdropHandoff(
        rateInfoSheet,
        rateInfoPanel,
        () => {
          sheetOpenWithInstantBackdrop(confirmSheet);
        },
        { suppressNestedScrim: true },
      );
    };

    rateRowOpenBtn?.addEventListener("click", () => openRateInfoSheet("convert-page"));
    rateInfoOpenBtn?.addEventListener("click", openFromConfirm);
    rateInfoSheet
      .querySelectorAll("[data-trade-convert-rate-info-close]")
      .forEach((btn) => btn.addEventListener("click", closeRateInfoSheet));
  };

  /** Trade · Convert — confirm quote bottom sheet (Figma 11243:5682). */
  const initTradeConvertConfirmSheet = () => {
    const sheet = document.querySelector("[data-trade-convert-confirm-sheet]");
    const previewBtn = document.querySelector("[data-trade-convert-preview]");
    if (!sheet || !previewBtn) return;

    const panel = sheet.querySelector(".currency-sheet__panel");
    const payHeroEl = sheet.querySelector("[data-trade-convert-confirm-pay-hero]");
    const recvHeroEl = sheet.querySelector("[data-trade-convert-confirm-recv-hero]");
    const payCodeEl = sheet.querySelector("[data-trade-convert-confirm-pay-code]");
    const recvCodeEl = sheet.querySelector("[data-trade-convert-confirm-recv-code]");
    const payIconEl = sheet.querySelector("[data-trade-convert-confirm-pay-icon]");
    const recvIconEl = sheet.querySelector("[data-trade-convert-confirm-recv-icon]");
    const fromEl = sheet.querySelector("[data-trade-convert-confirm-from]");
    const feeEl = sheet.querySelector("[data-trade-convert-confirm-fee]");
    const netEl = sheet.querySelector("[data-trade-convert-confirm-net]");
    const rateEl = sheet.querySelector("[data-trade-convert-confirm-rate]");
    const timerEl = sheet.querySelector("[data-trade-convert-confirm-timer]");
    const rateProgressEl = sheet.querySelector(
      "[data-trade-convert-confirm-progress]",
    );
    const recvLineEl = sheet.querySelector("[data-trade-convert-confirm-receive-line]");
    const confirmBtn = sheet.querySelector("[data-trade-convert-confirm-ok]");
    const updateRateBtn = sheet.querySelector("[data-trade-convert-confirm-update-rate]");
    const rateInfoSheet = document.querySelector(
      "[data-trade-convert-rate-info-sheet]",
    );
    const submitLoaderEl = document.querySelector(
      "[data-trade-convert-submit-loader]",
    );
    const postSheetEl = document.querySelector("[data-trade-convert-post-sheet]");
    const postSheetPanelEl = postSheetEl?.querySelector(".currency-sheet__panel");
    const postPayHeroEl = postSheetEl?.querySelector(
      "[data-trade-convert-post-pay-hero]",
    );
    const postRecvHeroEl = postSheetEl?.querySelector(
      "[data-trade-convert-post-recv-hero]",
    );
    const postPayCodeEl = postSheetEl?.querySelector(
      "[data-trade-convert-post-pay-code]",
    );
    const postRecvCodeEl = postSheetEl?.querySelector(
      "[data-trade-convert-post-recv-code]",
    );
    const postPayIconEl = postSheetEl?.querySelector(
      "[data-trade-convert-post-pay-icon]",
    );
    const postRecvIconEl = postSheetEl?.querySelector(
      "[data-trade-convert-post-recv-icon]",
    );
    const postBalanceTwdEl = postSheetEl?.querySelector(
      "[data-trade-convert-post-balance-twd]",
    );
    const postBalanceBtcEl = postSheetEl?.querySelector(
      "[data-trade-convert-post-balance-btc]",
    );

    const FEE_PCT = 0.001;
    const COUNTDOWN_START = 15;
    const SUBMIT_LOADER_MS = 2200;
    let countdownTimerId = null;
    let submitTimerId = null;

    const roundBtc = (n) => {
      if (!Number.isFinite(n)) return NaN;
      return Math.round(n * 1e6) / 1e6;
    };

    const roundFiat = (n) => {
      if (!Number.isFinite(n)) return NaN;
      return Math.round(n * 1e2) / 1e2;
    };

    const fmtFiat = (n) =>
      new Intl.NumberFormat("en-US", {
        minimumFractionDigits: 0,
        maximumFractionDigits: 2,
      }).format(Number.isFinite(n) ? n : 0);

    const fmtFiatFull = (n) =>
      new Intl.NumberFormat("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(Number.isFinite(n) ? n : 0);

    const fmtBtc = (n) =>
      Number.isFinite(n) ? roundBtc(n).toFixed(6) : "";

    const fmtTwdRate = (n) =>
      new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(
        Math.round(Number.isFinite(n) ? n : 0),
      );

    const iconFor = (code) => {
      const c = String(code || "").toUpperCase();
      if (c === "BTC") return "assets/icon_currency_btc.svg";
      if (c === "TWD") return "assets/icon_currency_TWD.svg";
      return "assets/icon_currency_usdt.svg";
    };

    const parseField = (raw, code) => {
      const x = parseFloat(String(raw || "").replace(/,/g, "").trim());
      if (!Number.isFinite(x)) return NaN;
      if (code === "BTC") return roundBtc(x);
      if (code === "TWD") return roundFiat(x);
      return roundFiat(x);
    };

    const formatCountdown = (sec) => {
      const s = Math.max(0, Math.floor(sec));
      const m = Math.floor(s / 60);
      const r = s % 60;
      return `Quote guaranteed for ${m}:${String(r).padStart(2, "0")}s`;
    };

    const stopCountdown = () => {
      if (countdownTimerId) {
        clearInterval(countdownTimerId);
        countdownTimerId = null;
      }
    };

    const hideSubmitLoader = () => {
      if (submitLoaderEl) submitLoaderEl.hidden = true;
    };

    const clearSubmitTimer = () => {
      if (submitTimerId) {
        clearTimeout(submitTimerId);
        submitTimerId = null;
      }
    };

    const closePostSheet = () => {
      if (!postSheetEl) return;
      postSheetEl.classList.remove("is-open");
      const onEnd = () => {
        if (!postSheetEl.classList.contains("is-open")) postSheetEl.hidden = true;
        postSheetPanelEl?.removeEventListener("transitionend", onEnd);
      };
      postSheetPanelEl?.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 290);
    };

    const openPostSheet = () => {
      if (!postSheetEl) return;
      postSheetEl.hidden = false;
      requestAnimationFrame(() => postSheetEl.classList.add("is-open"));
    };

    const clearRateExpired = () => {
      sheet.classList.remove("convert-confirm-sheet--rate-expired");
      if (confirmBtn) confirmBtn.disabled = false;
    };

    const applyRateExpired = () => {
      stopCountdown();
      sheet.classList.add("convert-confirm-sheet--rate-expired");
      if (rateEl) rateEl.textContent = "- -";
      if (recvHeroEl) recvHeroEl.textContent = "- -";
      const rc = recvCodeEl?.textContent?.trim() || "BTC";
      if (recvLineEl) recvLineEl.textContent = `- - ${rc}`;
      if (rateProgressEl) {
        // Snap to 0% at expiry (no trailing animation after 0:00).
        rateProgressEl.style.transition = "none";
        rateProgressEl.style.width = "0%";
      }
      if (confirmBtn) confirmBtn.disabled = true;
    };

    const startCountdown = () => {
      stopCountdown();
      clearRateExpired();
      let left = COUNTDOWN_START;
      if (timerEl) timerEl.textContent = formatCountdown(left);
      if (rateProgressEl) {
        // Refill instantly when a new quote starts.
        rateProgressEl.style.transition = "none";
        rateProgressEl.style.width = "100%";
        // Force style flush so subsequent countdown ticks animate normally.
        void rateProgressEl.offsetWidth;
        rateProgressEl.style.transition = "width 1s linear";
      }
      countdownTimerId = window.setInterval(() => {
        left -= 1;
        if (timerEl) timerEl.textContent = formatCountdown(Math.max(0, left));
        if (rateProgressEl) {
          const pct = (Math.max(0, left) / COUNTDOWN_START) * 100;
          rateProgressEl.style.width = `${pct}%`;
        }
        if (left <= 0) applyRateExpired();
      }, 1000);
    };

    const readRateTwdPerBtc = (root) => {
      const n = parseFloat(String(root?.getAttribute("data-convert-rate") || ""));
      return Number.isFinite(n) && n > 0 ? n : 2438104.61;
    };

    const syncFromConvert = () => {
      const root = document.querySelector("[data-trade-convert-root]");
      const payInp = root?.querySelector("[data-trade-convert-pay-input]");
      const recvInp = root?.querySelector("[data-trade-convert-recv-input]");
      const payCode =
        root
          ?.querySelector("[data-trade-convert-pay-currency]")
          ?.textContent?.trim() || "TWD";
      const recvCode =
        root
          ?.querySelector("[data-trade-convert-recv-currency]")
          ?.textContent?.trim() || "BTC";

      if (payIconEl) payIconEl.src = iconFor(payCode);
      if (recvIconEl) recvIconEl.src = iconFor(recvCode);
      if (payCodeEl) payCodeEl.textContent = payCode;
      if (recvCodeEl) recvCodeEl.textContent = recvCode;

      const payAmt = parseField(payInp?.value, payCode);
      const recvAmt = parseField(recvInp?.value, recvCode);

      if (payHeroEl)
        payHeroEl.textContent =
          payCode === "BTC" ? fmtBtc(payAmt) : fmtFiat(payAmt);
      if (recvHeroEl)
        recvHeroEl.textContent =
          recvCode === "BTC" ? fmtBtc(recvAmt) : fmtFiat(recvAmt);

      const fromStr =
        payCode === "BTC"
          ? `${fmtBtc(payAmt)} ${payCode}`
          : `${fmtFiatFull(payAmt)} ${payCode}`;
      if (fromEl) fromEl.textContent = fromStr;

      let fee = Number.isFinite(payAmt) ? payAmt * FEE_PCT : NaN;
      if (payCode === "BTC") fee = roundBtc(fee);
      else fee = roundFiat(fee);

      const net = Number.isFinite(payAmt) && Number.isFinite(fee)
        ? payCode === "BTC"
          ? roundBtc(payAmt - fee)
          : roundFiat(payAmt - fee)
        : NaN;

      if (feeEl)
        feeEl.textContent =
          payCode === "BTC"
            ? `${fmtBtc(fee)} ${payCode}`
            : `${fmtFiatFull(fee)} ${payCode}`;
      if (netEl)
        netEl.textContent =
          payCode === "BTC"
            ? `${fmtBtc(net)} ${payCode}`
            : `${fmtFiatFull(net)} ${payCode}`;

      const rate = readRateTwdPerBtc(root);
      if (rateEl)
        rateEl.textContent = `1 BTC = ${fmtTwdRate(rate)} TWD`;

      if (recvLineEl)
        recvLineEl.textContent =
          recvCode === "BTC"
            ? `${fmtBtc(recvAmt)} ${recvCode}`
            : `${fmtFiatFull(recvAmt)} ${recvCode}`;
    };

    const syncPostSheetFromConvert = () => {
      const root = document.querySelector("[data-trade-convert-root]");
      const payInp = root?.querySelector("[data-trade-convert-pay-input]");
      const recvInp = root?.querySelector("[data-trade-convert-recv-input]");
      const payCode =
        root
          ?.querySelector("[data-trade-convert-pay-currency]")
          ?.textContent?.trim() || "TWD";
      const recvCode =
        root
          ?.querySelector("[data-trade-convert-recv-currency]")
          ?.textContent?.trim() || "BTC";
      const payAmt = parseField(payInp?.value, payCode);
      const recvAmt = parseField(recvInp?.value, recvCode);

      if (postPayIconEl) postPayIconEl.src = iconFor(payCode);
      if (postRecvIconEl) postRecvIconEl.src = iconFor(recvCode);
      if (postPayCodeEl) postPayCodeEl.textContent = payCode;
      if (postRecvCodeEl) postRecvCodeEl.textContent = recvCode;
      if (postPayHeroEl)
        postPayHeroEl.textContent =
          payCode === "BTC" ? fmtBtc(payAmt) : fmtFiat(payAmt);
      if (postRecvHeroEl)
        postRecvHeroEl.textContent =
          recvCode === "BTC" ? fmtBtc(recvAmt) : fmtFiat(recvAmt);

      const nextBalances = {
        TWD: Number(PROTOTYPE_BALANCES.TWD) || 0,
        BTC: Number(PROTOTYPE_BALANCES.BTC) || 0,
      };
      if (Number.isFinite(payAmt) && payAmt > 0 && nextBalances[payCode] != null) {
        nextBalances[payCode] = Math.max(0, nextBalances[payCode] - payAmt);
      }
      if (
        Number.isFinite(recvAmt) &&
        recvAmt > 0 &&
        nextBalances[recvCode] != null
      ) {
        nextBalances[recvCode] += recvAmt;
      }

      if (postBalanceTwdEl)
        postBalanceTwdEl.textContent = `${fmtFiatFull(nextBalances.TWD)} TWD`;
      if (postBalanceBtcEl)
        postBalanceBtcEl.textContent = `${fmtBtc(nextBalances.BTC)} BTC`;
    };

    const close = (opts = {}) => {
      clearSubmitTimer();
      hideSubmitLoader();
      stopCountdown();
      clearRateExpired();
      if (rateInfoSheet) {
        rateInfoSheet.classList.remove("is-open");
        rateInfoSheet.hidden = true;
      }
      if (opts.instant) {
        sheet.hidden = true;
        sheet.classList.remove("is-open");
        return;
      }
      sheet.classList.remove("is-open");
      const onEnd = () => {
        if (!sheet.classList.contains("is-open")) sheet.hidden = true;
        panel?.removeEventListener("transitionend", onEnd);
      };
      panel?.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 290);
    };

    const open = () => {
      if (previewBtn.disabled) return;
      clearRateExpired();
      syncFromConvert();
      startCountdown();
      if (rateInfoSheet) {
        rateInfoSheet.classList.remove("is-open");
        rateInfoSheet.hidden = true;
      }
      sheet.hidden = false;
      requestAnimationFrame(() => sheet.classList.add("is-open"));
    };

    previewBtn.addEventListener("click", open);
    sheet.querySelectorAll("[data-trade-convert-confirm-close]").forEach((btn) => {
      btn.addEventListener("click", close);
    });
    confirmBtn?.addEventListener("click", () => {
      if (confirmBtn.disabled) return;
      clearSubmitTimer();
      stopCountdown();
      hideSubmitLoader();
      if (submitLoaderEl) submitLoaderEl.hidden = false;
      submitTimerId = window.setTimeout(() => {
        submitTimerId = null;
        hideSubmitLoader();
        close({ instant: true });
        syncPostSheetFromConvert();
        openPostSheet();

        // Reset convert form back to empty after submitting.
        const convertRoot = document.querySelector("[data-trade-convert-root]");
        const payInp = convertRoot?.querySelector("[data-trade-convert-pay-input]");
        const recvInp = convertRoot?.querySelector(
          "[data-trade-convert-recv-input]",
        );
        if (payInp) payInp.value = "";
        if (recvInp) recvInp.value = "";
        // Trigger normal UI sync (hints, disabled Preview, etc.)
        payInp?.dispatchEvent(new Event("input", { bubbles: true }));
      }, SUBMIT_LOADER_MS);
    });
    updateRateBtn?.addEventListener("click", () => {
      clearRateExpired();
      syncFromConvert();
      startCountdown();
    });
    postSheetEl
      ?.querySelectorAll("[data-trade-convert-post-close]")
      .forEach((btn) => btn.addEventListener("click", closePostSheet));
  };

  const initTradeConvertHistoryPage = () => {
    if (initTradeConvertHistoryPage._inited) return;
    const page = document.querySelector("[data-trade-convert-history-page]");
    const openTriggers = Array.from(
      document.querySelectorAll(
        "[data-trade-convert-history-open], [data-trade-history-open]",
      ),
    );
    if (!page || !openTriggers.length) return;
    initTradeConvertHistoryPage._inited = true;
    const tabBtns = Array.from(
      page.querySelectorAll("[data-trade-convert-history-tab]"),
    );
    const panelsViewport = page.querySelector(
      "[data-trade-convert-history-panels-viewport]",
    );
    const panelsTrack = page.querySelector(
      "[data-trade-convert-history-panels-track]",
    );
    const panels = Array.from(
      panelsTrack?.querySelectorAll("[data-trade-convert-history-panel]") || [],
    );
    const activityDetailPanel = document.querySelector(
      "[data-my-plans-activity-detail-panel]",
    );
    const tabsScroll = page.querySelector("[data-trade-convert-history-tabs-scroll]");
    const tabsIndicator = page.querySelector("[data-trade-convert-history-tabs-indicator]");
    const tabCount = tabBtns.length;

    if (panelsViewport && tabCount > 0) {
      panelsViewport.style.setProperty("--history-tab-count", String(tabCount));
    }

    const syncHistoryTabsIndicator = () => {
      if (!tabsScroll || !tabsIndicator) return;
      const active = tabsScroll.querySelector(".app-header__tab.is-active");
      if (!active) return;
      const tabLeft = active.offsetLeft;
      const tabW = active.offsetWidth;
      const indicatorW = Math.min(24, Math.max(16, tabW - 8));
      const x = tabLeft + (tabW - indicatorW) / 2;
      tabsIndicator.style.width = `${indicatorW}px`;
      tabsIndicator.style.transform = `translateX(${x}px)`;
    };

    const applyHistoryPanelsOffset = (index, instant) => {
      if (!panelsTrack || tabCount <= 0) return;
      const pct = (index / tabCount) * 100;
      if (instant) panelsTrack.classList.add("is-instant");
      panelsTrack.style.transform = `translateX(-${pct}%)`;
      if (instant) {
        requestAnimationFrame(() => {
          panelsTrack.classList.remove("is-instant");
        });
      }
    };

    const setHistoryTab = (tabId, opts = {}) => {
      const { scrollTab = true, instant = false } = opts;
      const idx = tabBtns.findIndex(
        (b) => b.getAttribute("data-trade-convert-history-tab") === tabId,
      );
      if (idx < 0) return;

      tabBtns.forEach((btn, i) => {
        btn.classList.toggle("is-active", i === idx);
      });

      applyHistoryPanelsOffset(idx, instant);

      const activeBtn = tabBtns[idx];
      if (scrollTab && activeBtn && tabsScroll) {
        activeBtn.scrollIntoView({
          behavior: "smooth",
          inline: "center",
          block: "nearest",
        });
      }
      requestAnimationFrame(() => {
        syncHistoryTabsIndicator();
        requestAnimationFrame(() => syncHistoryTabsIndicator());
      });
    };

    const close = (opts = {}) => {
      if (!page.classList.contains("is-open") && page.hidden) return;
      if (opts.instant) {
        page.classList.remove("is-open");
        page.hidden = true;
        return;
      }
      page.classList.remove("is-open");
      const onEnd = () => {
        if (!page.classList.contains("is-open")) page.hidden = true;
        page.removeEventListener("transitionend", onEnd);
      };
      page.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 320);
    };

    const open = (tabId = "convert") => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-hide"));
      syncEarnHistoryPanel();
      setHistoryTab(tabId, {
        scrollTab: false,
        instant: true,
      });
      page.hidden = false;
      panels.forEach((p) => {
        if (p.getAttribute("data-trade-convert-history-panel") === tabId) {
          p.scrollTop = 0;
        }
      });
      requestAnimationFrame(() => {
        page.classList.add("is-open");
        const activeBtn = tabBtns.find((b) =>
          b.classList.contains("is-active"),
        );
        if (activeBtn && tabsScroll) {
          activeBtn.scrollIntoView({
            behavior: "instant",
            inline: "center",
            block: "nearest",
          });
        }
        syncHistoryTabsIndicator();
        requestAnimationFrame(() => {
          syncHistoryTabsIndicator();
        });
      });
    };

    const setActivityDetailRowVisibility = (visibleKeys = []) => {
      if (!activityDetailPanel) return;
      const visibleSet = new Set(visibleKeys);
      const metaList = activityDetailPanel.querySelector(
        ".my-plans-activity-detail-panel__meta-list",
      );
      const rows = Array.from(
        metaList?.querySelectorAll("[data-my-plans-activity-detail-row]") || [],
      );
      rows.forEach((row) => {
        const key = row.getAttribute("data-my-plans-activity-detail-row");
        if (key === "fee") {
          row.hidden = true;
          return;
        }
        row.hidden = !visibleSet.has(String(key || ""));
      });
      const dividers = Array.from(
        metaList?.querySelectorAll(".my-plans-activity-detail-panel__divider") || [],
      );
      dividers.forEach((divider, idx) => {
        const prev = rows[idx];
        const next = rows[idx + 1];
        divider.hidden =
          !prev ||
          !next ||
          prev.hidden ||
          (next.hidden &&
            next.getAttribute("data-my-plans-activity-detail-row") !== "fee");
      });
    };

    const extractAmountAndCurrency = (rawText) => {
      const text = String(rawText || "").replace(/\s+/g, " ").trim();
      const m = text.match(/([+-]?\s*[\d,]*\.?\d+)\s*([A-Z]{2,8})/);
      if (!m) return { amount: NaN, currency: "" };
      const amount = parseFloat(String(m[1]).replace(/[,\s]/g, ""));
      const currency = String(m[2] || "").trim().toUpperCase();
      return { amount, currency };
    };

    const openConvertHistoryDetail = (row) => {
      if (!activityDetailPanel || !row) return;
      const setText = (selector, value) => {
        const el = activityDetailPanel.querySelector(selector);
        if (!el) return;
        el.textContent = String(value ?? "");
      };
      const titleEl = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-title]",
      );
      if (titleEl) titleEl.textContent = "Convert order";
      const toLabelEl = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-to-label]",
      );
      if (toLabelEl) toLabelEl.textContent = "You received";
      const heroDateEl = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-hero-date]",
      );
      if (heroDateEl) heroDateEl.hidden = false;

      const pairText = String(
        row.querySelector(".trade-convert-history-item__pair")?.textContent || "",
      ).trim();
      const dateText = String(
        row.querySelector(".trade-convert-history-item__date")?.textContent || "",
      ).trim();
      const receiveText = String(
        row.querySelector(".trade-convert-history-item__receive")?.textContent || "",
      ).trim();
      const payText = String(
        row.querySelector(".trade-convert-history-item__pay")?.textContent || "",
      ).trim();
      setText("[data-my-plans-activity-detail-convert-pair]", pairText || "TWD → BTC");
      setText("[data-my-plans-activity-detail-hero-date]", dateText || "18/12/2025, 08:38:29");
      setText("[data-my-plans-activity-detail-from]", payText || "- 5,000.00 TWD");
      setText("[data-my-plans-activity-detail-to]", receiveText || "+ 0.0453 BTC");

      const fromIcon = row.querySelector(".trade-convert-history-item__coin--from");
      const toIcon = row.querySelector(".trade-convert-history-item__coin--to");
      const detailFromIcon = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-icon-from]",
      );
      const detailToIcon = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-icon-to]",
      );
      if (detailFromIcon && fromIcon?.getAttribute("src")) {
        detailFromIcon.setAttribute("src", fromIcon.getAttribute("src"));
      }
      if (detailToIcon && toIcon?.getAttribute("src")) {
        detailToIcon.setAttribute("src", toIcon.getAttribute("src"));
      }

      const payParsed = extractAmountAndCurrency(payText);
      const recvParsed = extractAmountAndCurrency(receiveText);
      let priceText = "1 BTC = 594,004.23 TWD";
      if (
        Number.isFinite(payParsed.amount) &&
        Number.isFinite(recvParsed.amount) &&
        Math.abs(recvParsed.amount) > 0 &&
        payParsed.currency &&
        recvParsed.currency
      ) {
        const unitPrice = Math.abs(payParsed.amount) / Math.abs(recvParsed.amount);
        priceText = `1 ${recvParsed.currency} = ${unitPrice.toLocaleString("en-US", {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        })} ${payParsed.currency}`;
      }
      setText("[data-my-plans-activity-detail-avg-price]", priceText);
      setText(
        "[data-my-plans-activity-detail-fee]",
        `3.25159 ${payParsed.currency || "TWD"}`,
      );
      setText("[data-my-plans-activity-detail-order-id]", "1219286689");

      setActivityDetailRowVisibility(["price", "order-id"]);

      // Convert order detail (Figma 11282:7063) does not show auto-invest specific rows.
      ["status", "via-plan", "paid-with"].forEach((k) => {
        const rowEl = activityDetailPanel.querySelector(
          `[data-my-plans-activity-detail-row="${k}"]`,
        );
        if (rowEl) rowEl.hidden = true;
      });

      activityDetailPanel.hidden = false;
      requestAnimationFrame(() => {
        activityDetailPanel.classList.add("is-open");
      });
    };

    const openAutoInvestHistoryDetail = (row) => {
      if (!activityDetailPanel || !row) return;
      const setText = (selector, value) => {
        const el = activityDetailPanel.querySelector(selector);
        if (!el) return;
        el.textContent = String(value ?? "");
      };
      const titleEl = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-title]",
      );
      if (titleEl) titleEl.textContent = "DCA order";
      const toLabelEl = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-to-label]",
      );
      if (toLabelEl) toLabelEl.textContent = "To";
      const heroDateEl = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-hero-date]",
      );
      if (heroDateEl) heroDateEl.hidden = false;

      const pairText = String(
        row.querySelector(".trade-convert-history-item__pair")?.textContent || "",
      ).trim();
      const dateText = String(
        row.querySelector(".trade-convert-history-item__date")?.textContent || "",
      ).trim();
      const receiveText = String(
        row.querySelector(".trade-convert-history-item__receive")?.textContent || "",
      ).trim();
      const payText = String(
        row.querySelector(".trade-convert-history-item__pay")?.textContent || "",
      ).trim();
      setText("[data-my-plans-activity-detail-convert-pair]", pairText || "TWD → BTC");
      setText(
        "[data-my-plans-activity-detail-hero-date]",
        dateText || "18/12/2025, 08:38:29",
      );
      setText("[data-my-plans-activity-detail-from]", payText || "- 5,000.00 TWD");
      setText("[data-my-plans-activity-detail-to]", receiveText || "+ 0.0453 BTC");

      const fromIcon = row.querySelector(".trade-convert-history-item__coin--from");
      const toIcon = row.querySelector(".trade-convert-history-item__coin--to");
      const detailFromIcon = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-icon-from]",
      );
      const detailToIcon = activityDetailPanel.querySelector(
        "[data-my-plans-activity-detail-icon-to]",
      );
      if (detailFromIcon && fromIcon?.getAttribute("src")) {
        detailFromIcon.setAttribute("src", fromIcon.getAttribute("src"));
      }
      if (detailToIcon && toIcon?.getAttribute("src")) {
        detailToIcon.setAttribute("src", toIcon.getAttribute("src"));
      }

      const payParsed = extractAmountAndCurrency(payText);
      const recvParsed = extractAmountAndCurrency(receiveText);
      let priceText = "1 BTC = 594,004.23 TWD";
      if (
        Number.isFinite(payParsed.amount) &&
        Number.isFinite(recvParsed.amount) &&
        Math.abs(recvParsed.amount) > 0 &&
        payParsed.currency &&
        recvParsed.currency
      ) {
        const unitPrice = Math.abs(payParsed.amount) / Math.abs(recvParsed.amount);
        priceText = `1 ${recvParsed.currency} = ${unitPrice.toLocaleString("en-US", {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        })} ${payParsed.currency}`;
      }
      setText("[data-my-plans-activity-detail-avg-price]", priceText);
      setText(
        "[data-my-plans-activity-detail-fee]",
        `3.25159 ${payParsed.currency || "TWD"}`,
      );
      setText("[data-my-plans-activity-detail-order-id]", "1453537");
      setText("[data-my-plans-activity-detail-plan-id]", "5419286689");
      setText(
        "[data-my-plans-activity-detail-paid-with]",
        `pre-funded ${payParsed.currency || "TWD"}`,
      );

      setActivityDetailRowVisibility([
        "price",
        "order-id",
        "via-plan",
        "paid-with",
      ]);
      ["status", "date"].forEach((k) => {
        const rowEl = activityDetailPanel.querySelector(
          `[data-my-plans-activity-detail-row="${k}"]`,
        );
        if (rowEl) rowEl.hidden = true;
      });
      const metaList = activityDetailPanel.querySelector(
        ".my-plans-activity-detail-panel__meta-list",
      );
      const rows = Array.from(
        metaList?.querySelectorAll("[data-my-plans-activity-detail-row]") || [],
      );
      const dividers = Array.from(
        metaList?.querySelectorAll(".my-plans-activity-detail-panel__divider") || [],
      );
      dividers.forEach((divider, idx) => {
        const prev = rows[idx];
        const next = rows[idx + 1];
        divider.hidden =
          !prev ||
          !next ||
          prev.hidden ||
          (next.hidden &&
            next.getAttribute("data-my-plans-activity-detail-row") !== "fee");
      });

      activityDetailPanel.hidden = false;
      requestAnimationFrame(() => {
        activityDetailPanel.classList.add("is-open");
      });
    };

    openTriggers.forEach((btn) => {
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const tabId =
          btn.getAttribute("data-trade-history-tab") ||
          (btn.hasAttribute("data-trade-convert-history-open") ? "convert" : "spot");
        open(tabId);
      });
    });
    tabsScroll?.addEventListener("scroll", () => syncHistoryTabsIndicator(), {
      passive: true,
    });
    window.addEventListener("resize", () => {
      if (page.classList.contains("is-open")) syncHistoryTabsIndicator();
    });
    tabBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        setHistoryTab(btn.getAttribute("data-trade-convert-history-tab"));
      });
    });
    page
      .querySelectorAll("[data-trade-convert-history-open-detail]")
      .forEach((rowBtn) => {
        rowBtn.addEventListener("click", () => openConvertHistoryDetail(rowBtn));
      });
    page
      .querySelectorAll("[data-trade-convert-history-open-auto-invest-detail]")
      .forEach((rowBtn) => {
        rowBtn.addEventListener("click", () =>
          openAutoInvestHistoryDetail(rowBtn),
        );
      });
    page
      .querySelectorAll("[data-trade-convert-history-close]")
      .forEach((btn) => {
        btn.addEventListener("click", close);
      });
    setHistoryTab("convert", { scrollTab: false, instant: true });
  };

  const initEarnAllocationDetailPage = () => {
    if (initEarnAllocationDetailPage._inited) return;
    const page = document.querySelector("[data-earn-allocation-detail-page]");
    if (!page) return;
    initEarnAllocationDetailPage._inited = true;

    const open = () => {
      syncEarnAllocationDetailPage();
      page.hidden = false;
      requestAnimationFrame(() => page.classList.add("is-open"));
    };

    const close = () => {
      page.classList.remove("is-open");
      const onEnd = () => {
        if (!page.classList.contains("is-open")) page.hidden = true;
        page.removeEventListener("transitionend", onEnd);
      };
      page.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 400);
    };

    document.querySelectorAll("[data-earn-allocation-detail-open]").forEach((btn) => {
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        open();
      });
    });
    page
      .querySelectorAll("[data-earn-allocation-detail-close]")
      .forEach((btn) => {
        btn.addEventListener("click", close);
      });
  };

  const formatEarnYieldPayoutDetailAmount = (listValue) => {
    if (!listValue) return "";
    return listValue.replace(/^\+\s*/, "").trim();
  };

  const initEarnYieldPayoutDetailPage = () => {
    if (initEarnYieldPayoutDetailPage._inited) return;
    const page = document.querySelector("[data-earn-yield-payout-detail-page]");
    if (!page) return;
    initEarnYieldPayoutDetailPage._inited = true;

    const amountEl = page.querySelector("[data-earn-yield-payout-detail-amount]");
    const dateEl = page.querySelector("[data-earn-yield-payout-detail-date]");
    const tidEl = page.querySelector("[data-earn-yield-payout-detail-tid]");

    const populateFromRow = (row) => {
      const valueEl = row.querySelector(".trade-earn-history-item__value");
      const rowDateEl = row.querySelector(".trade-earn-history-item__date");
      if (amountEl && valueEl) {
        amountEl.textContent = formatEarnYieldPayoutDetailAmount(valueEl.textContent);
      }
      if (dateEl && rowDateEl) dateEl.textContent = rowDateEl.textContent.trim();
      if (tidEl) {
        tidEl.textContent = row.dataset.earnYieldPayoutTid || "—";
      }
    };

    const open = (row) => {
      populateFromRow(row);
      page.hidden = false;
      requestAnimationFrame(() => page.classList.add("is-open"));
    };

    const close = () => {
      page.classList.remove("is-open");
      const onEnd = () => {
        if (!page.classList.contains("is-open")) page.hidden = true;
        page.removeEventListener("transitionend", onEnd);
      };
      page.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 400);
    };

    document.querySelectorAll("[data-earn-yield-payout-detail-open]").forEach((btn) => {
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        open(btn);
      });
    });
    page
      .querySelectorAll("[data-earn-yield-payout-detail-close]")
      .forEach((btn) => {
        btn.addEventListener("click", close);
      });
  };

  const initEarnPositionPage = () => {
    if (initEarnPositionPage._inited) return;
    const page = document.querySelector("[data-earn-position-page]");
    if (!page) return;
    initEarnPositionPage._inited = true;

    const container = document.querySelector(".phone-container");
    const scrollEl = page.querySelector(".earn-position-page__scroll");
    const countdown = {
      h: page.querySelector("[data-earn-position-countdown-h]"),
      m: page.querySelector("[data-earn-position-countdown-m]"),
      s: page.querySelector("[data-earn-position-countdown-s]"),
    };
    let countdownTimer = null;

    const padCountdown = (value) => String(value).padStart(2, "0");

    const getNextYieldCountdown = () => {
      const now = new Date();
      const next = new Date(now);
      next.setHours(12, 0, 0, 0);
      if (now >= next) next.setDate(next.getDate() + 1);
      const totalSec = Math.max(0, Math.floor((next - now) / 1000));
      return {
        h: Math.floor(totalSec / 3600),
        m: Math.floor((totalSec % 3600) / 60),
        s: totalSec % 60,
      };
    };

    const updateCountdown = () => {
      const parts = getNextYieldCountdown();
      if (countdown.h) countdown.h.textContent = padCountdown(parts.h);
      if (countdown.m) countdown.m.textContent = padCountdown(parts.m);
      if (countdown.s) countdown.s.textContent = padCountdown(parts.s);
    };

    const startCountdown = () => {
      updateCountdown();
      if (countdownTimer) clearInterval(countdownTimer);
      countdownTimer = setInterval(updateCountdown, 1000);
    };

    const stopCountdown = () => {
      if (!countdownTimer) return;
      clearInterval(countdownTimer);
      countdownTimer = null;
    };

    const setContainerOpen = (nextOpen) => {
      if (!container) return;
      if (nextOpen) {
        container.classList.remove("is-earn-position-open");
        container.classList.remove("is-earn-position-fading");
        setTimeout(() => {
          if (page.classList.contains("is-open")) {
            container.classList.add("is-earn-position-fading");
          }
        }, 80);
        setTimeout(() => {
          if (page.classList.contains("is-open")) {
            container.classList.add("is-earn-position-open");
          }
        }, 350);
        return;
      }
      container.classList.add("is-earn-position-fading");
      container.classList.remove("is-earn-position-open");
      requestAnimationFrame(() => {
        container.classList.remove("is-earn-position-fading");
      });
    };

    const open = () => {
      syncEarnPositionPage();
      page.hidden = false;
      setContainerOpen(true);
      if (scrollEl) scrollEl.scrollTop = 0;
      requestAnimationFrame(() => {
        page.classList.add("is-open");
        startCountdown();
      });
    };

    const close = (opts = {}) => {
      stopCountdown();
      setContainerOpen(false);
      if (opts.instant) {
        page.classList.remove("is-open");
        page.hidden = true;
        return;
      }
      page.classList.remove("is-open");
      const onEnd = () => {
        if (!page.classList.contains("is-open")) page.hidden = true;
        page.removeEventListener("transitionend", onEnd);
      };
      page.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 400);
    };

    document.querySelectorAll("[data-earn-position-open]").forEach((trigger) => {
      trigger.addEventListener("click", (event) => {
        event.preventDefault();
        open();
      });
      trigger.addEventListener("keydown", (event) => {
        if (event.key !== "Enter" && event.key !== " ") return;
        event.preventDefault();
        open();
      });
    });

    page.querySelectorAll("[data-earn-position-close]").forEach((btn) => {
      btn.addEventListener("click", () => close());
    });

    page
      .querySelector("[data-earn-position-history-more]")
      ?.addEventListener("click", () => {
        close({ instant: true });
        document
          .querySelector('[data-trade-history-open][data-trade-history-tab="earn"]')
          ?.click();
      });

    page.querySelectorAll("[data-earn-position-chart-mode]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const mode = btn.getAttribute("data-earn-position-chart-mode");
        if (!mode || mode === earnPositionChartMode) return;
        syncEarnPositionChartMode(page, mode);
      });
    });
  };

  const initTradeConvertHistoryCurrencySheet = () => {
    const sheet = document.querySelector(
      "[data-trade-convert-history-currency-sheet]",
    );
    if (!sheet) return;
    const searchInput = sheet.querySelector(
      "[data-trade-convert-history-currency-search]",
    );
    const options = Array.from(
      sheet.querySelectorAll("[data-trade-convert-history-currency-option]"),
    );
    const allOption = sheet.querySelector(
      '[data-trade-convert-history-currency-option="all"]',
    );
    const triggers = Array.from(
      document.querySelectorAll(
        "[data-trade-convert-history-filter-currency-trigger]",
      ),
    );
    let selectedValue = "all";
    let currencySheetScope = "default";
    const RADIO_OFF_ICON = "assets/icon_radio_off.svg";
    const RADIO_ON_ICON = "assets/icon_radio_on.svg";
    const ALL_CURRENCIES_LABEL = "All currencies";
    const ALL_PAIRS_LABEL = "All pairs";

    const getHistoryPanelId = (el) =>
      String(
        el?.closest?.("[data-trade-convert-history-panel]")?.getAttribute(
          "data-trade-convert-history-panel",
        ) || "",
      );

    const getAllFilterLabel = (scope) =>
      scope === "convert" ? ALL_PAIRS_LABEL : ALL_CURRENCIES_LABEL;

    const syncHistoryCurrencyFilterLabels = () => {
      document
        .querySelectorAll("[data-trade-convert-history-panel]")
        .forEach((panel) => {
          const label = panel.querySelector(
            "[data-trade-convert-history-filter-currency-label]",
          );
          if (!label) return;
          const panelId = panel.getAttribute("data-trade-convert-history-panel");
          label.textContent = getAllFilterLabel(
            panelId === "convert" ? "convert" : "default",
          );
        });
    };

    const syncSheetAllOptionLabel = (scope) => {
      if (!allOption) return;
      const label = getAllFilterLabel(scope);
      allOption.setAttribute(
        "data-trade-convert-history-currency-option-label",
        label,
      );
      const nameEl = allOption.querySelector(
        ".trade-convert-history-currency-sheet__name",
      );
      if (nameEl) nameEl.textContent = label;
    };

    const applySelected = (value) => {
      selectedValue = value;
      options.forEach((opt) => {
        const isSelected =
          opt.getAttribute("data-trade-convert-history-currency-option") === value;
        opt.classList.toggle("is-selected", isSelected);
        const radioImg = opt.querySelector(
          ".trade-convert-history-currency-sheet__radio",
        );
        if (radioImg) radioImg.setAttribute("src", isSelected ? RADIO_ON_ICON : RADIO_OFF_ICON);
      });
      syncHistoryCurrencyFilterLabels();
      syncSheetAllOptionLabel(currencySheetScope);
    };

    const close = (opts = {}) => {
      const finish = () => {
        if (!sheet.classList.contains("is-open")) sheet.hidden = true;
      };
      if (opts.instant) {
        sheet.style.transition = "none";
        sheet.classList.remove("is-open");
        void sheet.offsetHeight;
        sheet.style.transition = "";
        finish();
        return;
      }
      sheet.classList.remove("is-open");
      const onEnd = () => {
        sheet.removeEventListener("transitionend", onEnd);
        finish();
      };
      sheet.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 360);
    };

    const open = () => {
      if (searchInput) searchInput.value = "";
      options.forEach((opt) => {
        opt.hidden = false;
      });
      applySelected(selectedValue);
      sheet.hidden = false;
      requestAnimationFrame(() => {
        sheet.classList.add("is-open");
      });
      requestAnimationFrame(() => {
        searchInput?.focus();
      });
    };

    triggers.forEach((btn) => {
      btn.addEventListener("click", () => {
        const panelId = getHistoryPanelId(btn);
        currencySheetScope = panelId === "convert" ? "convert" : "default";
        syncSheetAllOptionLabel(currencySheetScope);
        open();
      });
    });
    sheet
      .querySelectorAll("[data-trade-convert-history-currency-close]")
      .forEach((btn) => {
        btn.addEventListener("click", close);
      });
    options.forEach((opt) => {
      opt.addEventListener("click", () => {
        applySelected("all");
        close();
      });
    });
    searchInput?.addEventListener("input", () => {
      const q = String(searchInput.value || "")
        .trim()
        .toLowerCase();
      options.forEach((opt) => {
        const label = String(
          opt.getAttribute("data-trade-convert-history-currency-option-label") ||
            "",
        ).toLowerCase();
        opt.hidden = !!q && !label.includes(q);
      });
    });

    syncHistoryCurrencyFilterLabels();
    applySelected(selectedValue);
  };

  const initTradeConvertHistoryTimeSheet = () => {
    const sheet = document.querySelector("[data-trade-convert-history-time-sheet]");
    if (!sheet) return;
    const panel = sheet.querySelector(".currency-sheet__panel");
    if (!panel) return;
    const options = Array.from(
      sheet.querySelectorAll("[data-trade-convert-history-time-option]"),
    );
    const triggers = Array.from(
      document.querySelectorAll("[data-trade-convert-history-filter-time-trigger]"),
    );
    const triggerLabels = Array.from(
      document.querySelectorAll("[data-trade-convert-history-filter-time-label]"),
    );
    const RADIO_OFF_ICON = "assets/icon_radio_off.svg";
    const RADIO_ON_ICON = "assets/icon_radio_on.svg";
    let selectedValue = "All time";

    const applySelected = (value) => {
      selectedValue = value;
      options.forEach((opt) => {
        const optionValue =
          opt.getAttribute("data-trade-convert-history-time-option") || "";
        const isSelected = optionValue === value;
        opt.classList.toggle("is-selected", isSelected);
        const radioEl = opt.querySelector(
          ".trade-convert-history-time-sheet__item-radio",
        );
        if (radioEl) radioEl.setAttribute("src", isSelected ? RADIO_ON_ICON : RADIO_OFF_ICON);
      });
      triggerLabels.forEach((el) => {
        el.textContent = selectedValue;
      });
    };

    const open = () => {
      applySelected(selectedValue);
      sheetOpenWithInstantBackdrop(sheet);
    };

    const close = () => {
      sheetCloseWithBackdropHandoff(sheet, panel);
    };

    triggers.forEach((btn) => {
      btn.addEventListener("click", open);
    });
    sheet
      .querySelectorAll("[data-trade-convert-history-time-close]")
      .forEach((btn) => {
        btn.addEventListener("click", close);
      });
    options.forEach((opt) => {
      opt.addEventListener("click", () => {
        const value =
          opt.getAttribute("data-trade-convert-history-time-option") || "All time";
        applySelected(value);
        close();
      });
    });

    applySelected(selectedValue);
  };

  let ensureFinanceModulesInited = () => {};
  let ensureConvertModulesInited = () => {};

  let convertModulesInited = false;
  ensureConvertModulesInited = () => {
    if (convertModulesInited) return;
    convertModulesInited = true;
    initTradeConvertPage();
    initTradeConvertRatePanel();
    initTradeConvertConfirmSheet();
    initTradeConvertHistoryPage();
    initEarnAllocationDetailPage();
    initEarnYieldPayoutDetailPage();
    initTradeConvertHistoryCurrencySheet();
    initTradeConvertHistoryTimeSheet();
  };

  const earnRewardChart = (() => {
    const REWARD_RATE = 169.983 / 2000;
    const BANK_REWARD_RATE = 41.44 / 2000;
    const REFERENCE_PRINCIPAL = 2000;
    const Y_AXIS_PADDING_TOP = 30;
    const Y_AXIS_REF = { min: 2000, max: 2200 };
    const Y_TICKS_REF = [2000, 2050, 2100, 2150];
    const MONTHS = [0, 2, 4, 6, 8, 10, 12];
    const X_LABELS = ["Now", "2M", "4M", "6M", "8M", "10M", "1Y"];
    const SVG_WIDTH = 328;
    const CHART = { top: 10, bottom: 172, labelGap: 4 };
    const CLASS_PREFIX = "earn-rewards-learn-page";

    const estimateLabelWidth = (text) => text.length * 6.5;

    const parseStakeAmount = (raw) => {
      const cleaned = String(raw ?? "")
        .replace(/,/g, "")
        .trim();
      if (!cleaned) return 0;
      const parsed = Number.parseFloat(cleaned);
      return Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
    };

    const formatLearnReward = (value) => {
      const rounded = Math.round(value * 1000) / 1000;
      return `+ ${rounded.toLocaleString("en-US", {
        minimumFractionDigits: 3,
        maximumFractionDigits: 3,
      })} USDT`;
    };

    const formatStakingReward = (value) => {
      const rounded = Math.round(value * 100) / 100;
      return `≈${rounded.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      })} USDT`;
    };

    const formatEndLabel = (value) => {
      if (value >= 1_000_000) {
        return value.toLocaleString("en-US", {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        });
      }
      return value.toLocaleString("en-US", {
        minimumFractionDigits: 3,
        maximumFractionDigits: 6,
      });
    };

    const formatAxisLabel = (value) => {
      if (value >= 1_000_000_000) {
        return `${(value / 1_000_000_000).toLocaleString("en-US", {
          maximumFractionDigits: 2,
        })}B`;
      }
      if (value >= 1_000_000) {
        return `${(value / 1_000_000).toLocaleString("en-US", {
          maximumFractionDigits: 2,
        })}M`;
      }
      if (value >= 10_000) {
        return `${(value / 1_000).toLocaleString("en-US", {
          maximumFractionDigits: 1,
        })}K`;
      }
      if (value >= 1000) {
        return Math.round(value).toLocaleString("en-US");
      }
      if (value >= 100) {
        return Math.round(value).toString();
      }
      return value.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
    };

    const getLineEnds = (principal) => ({
      start: principal,
      xrexEnd: principal * (1 + REWARD_RATE),
      bankEnd: principal * (1 + BANK_REWARD_RATE),
    });

    const getAxisScale = (principal) => {
      if (principal <= 0) {
        return {
          min: Y_AXIS_REF.min,
          max: Y_AXIS_REF.max,
          ticks: Y_TICKS_REF,
        };
      }
      const scale = principal / REFERENCE_PRINCIPAL;
      const { xrexEnd } = getLineEnds(principal);
      const min = principal;
      const max = xrexEnd + Y_AXIS_PADDING_TOP * scale;
      const ticks = Y_TICKS_REF.map((_, index) => {
        const ratio = index / (Y_TICKS_REF.length - 1);
        return min + ratio * (max - min);
      });
      return { min, max, ticks };
    };

    const minLeftPadding = (() => {
      const axis = getAxisScale(200000);
      const yLabelTexts = axis.ticks.map(formatAxisLabel);
      const maxYLabelWidth = Math.max(
        0,
        ...yLabelTexts.map((text) => estimateLabelWidth(text)),
      );
      return Math.ceil(maxYLabelWidth) + CHART.labelGap;
    })();

    const getChartLayout = (axis) => {
      const yLabelTexts = axis.ticks.map(formatAxisLabel);
      const maxYLabelWidth = Math.max(
        0,
        ...yLabelTexts.map((text) => estimateLabelWidth(text)),
      );
      const left = Math.max(
        minLeftPadding,
        Math.ceil(maxYLabelWidth) + CHART.labelGap,
      );
      const right = SVG_WIDTH;
      return {
        left,
        right,
        labelX: left - CHART.labelGap,
        plotWidth: right - left,
      };
    };

    const yAtPixel = (tickIndex) => {
      const plotHeight = CHART.bottom - CHART.top;
      const ratio = tickIndex / (Y_TICKS_REF.length - 1);
      return CHART.bottom - ratio * plotHeight;
    };

    const lineValueAtMonth = (start, end, month) =>
      start + (end - start) * (month / 12);

    const yAt = (value, axisMin, axisMax) => {
      const plotHeight = CHART.bottom - CHART.top;
      const range = Math.max(axisMax - axisMin, 1);
      const clamped = Math.max(axisMin, Math.min(axisMax, value));
      return CHART.bottom - ((clamped - axisMin) / range) * plotHeight;
    };

    const CHART_DOT_RADIUS = 4;

    const cls = (suffix) => `${CLASS_PREFIX}__chart-${suffix}`;

    const renderChart = (chartSvg, principal) => {
      if (!chartSvg) return;
      const axis = getAxisScale(principal);
      const layout = getChartLayout(axis);
      const { start, xrexEnd, bankEnd } = getLineEnds(principal);
      const xrexValues = MONTHS.map((month) =>
        lineValueAtMonth(start, xrexEnd, month),
      );
      const bankValues = MONTHS.map((month) =>
        lineValueAtMonth(start, bankEnd, month),
      );

      const xAt = (index) =>
        layout.left + (index / (MONTHS.length - 1)) * layout.plotWidth;

      const toPath = (values) => {
        const startY = yAt(values[0], axis.min, axis.max);
        const endY = yAt(values[values.length - 1], axis.min, axis.max);
        const x0 = xAt(0);
        const x1 = xAt(MONTHS.length - 1);
        return `M${x0.toFixed(2)} ${startY.toFixed(2)} L${x1.toFixed(2)} ${endY.toFixed(2)}`;
      };

      const gridLines = Y_TICKS_REF.map((_, index) => {
        const y = yAtPixel(index).toFixed(2);
        return `<line class="${cls("grid-line")}" x1="${layout.left}" y1="${y}" x2="${layout.right}" y2="${y}" />`;
      }).join("");

      const yLabels = axis.ticks
        .map((tick, index) => {
          const y = yAtPixel(index) + 4;
          return `<text class="${cls("label")}" x="${layout.labelX}" y="${y}" text-anchor="end">${formatAxisLabel(tick)}</text>`;
        })
        .join("");

      const xLabels = X_LABELS.map((label, index) => {
        const x = xAt(index);
        return `<text class="${cls("label")}" x="${x}" y="190" text-anchor="middle">${label}</text>`;
      }).join("");

      const showLines = principal > 0;
      const endX = xAt(MONTHS.length - 1);
      const xrexEndY = yAt(xrexEnd, axis.min, axis.max);
      const bankEndY = yAt(bankEnd, axis.min, axis.max);
      const endLabels = showLines
        ? `<text class="${cls("end-label")}" x="${layout.right}" y="${xrexEndY - 8}">${formatEndLabel(xrexEnd)}</text>
        <text class="${cls("end-label")}" x="${layout.right}" y="${bankEndY - 8}">${formatEndLabel(bankEnd)}</text>`
        : "";

      const linePaths = showLines
        ? `<path class="${cls("line")} ${cls("line--bank")}" d="${toPath(bankValues)}" />
        <path class="${cls("line")} ${cls("line--xrex")}" d="${toPath(xrexValues)}" />`
        : "";

      const endDots = showLines
        ? `<circle class="earn-rewards-learn-page__apr-chart-dot earn-rewards-learn-page__apr-chart-dot--bank" cx="${endX.toFixed(2)}" cy="${bankEndY.toFixed(2)}" r="${CHART_DOT_RADIUS}" />
        <circle class="earn-rewards-learn-page__apr-chart-dot" cx="${endX.toFixed(2)}" cy="${xrexEndY.toFixed(2)}" r="${CHART_DOT_RADIUS}" />`
        : "";

      chartSvg.innerHTML = `
        ${gridLines}
        <line class="${cls("axis-line")}" x1="${layout.left}" y1="${CHART.bottom}" x2="${layout.right}" y2="${CHART.bottom}" />
        ${yLabels}
        ${xLabels}
        ${linePaths}
        ${endDots}
        ${endLabels}
      `;
    };

    const calcReward = (principal) => principal * REWARD_RATE;

    const APR_CHART_LAYOUT = {
      left: 38,
      right: 296,
      bottom: 137,
      yTicks: [
        { label: "7%", y: 20 },
        { label: "5%", y: 59 },
        { label: "3%", y: 98 },
        { label: "0%", y: 137 },
      ],
    };

    const aprToHistoryY = (apr) => {
      const top = APR_CHART_LAYOUT.yTicks[0].y;
      const bottom = APR_CHART_LAYOUT.bottom;
      return Math.round(bottom - (apr / 7) * (bottom - top));
    };

    const HISTORY_APR_X = [38, 78, 118, 158, 198, 238, 290];

    const historyAprPoints = (aprs) =>
      aprs.map((apr, index) => [HISTORY_APR_X[index], aprToHistoryY(apr)]);

    const aprToStakingY = (apr) => {
      const top = 10;
      const bottom = CHART.bottom;
      return Math.round(bottom - (apr / 7) * (bottom - top));
    };

    const STAKING_APR_X = [50, 88, 127, 168, 209, 249, 288, 328];

    const stakingAprPoints = (aprs) =>
      aprs.map((apr, index) => [STAKING_APR_X[index], aprToStakingY(apr)]);

    const formatAprChartDate = (date) =>
      date.toLocaleDateString("en-US", { month: "short", day: "numeric" });

    const getAprChartDateLabels = (rangeKey) => {
      const now = new Date();
      if (rangeKey === "all-time") {
        const start = new Date(now);
        start.setFullYear(start.getFullYear() - 2);
        const middle = new Date(now);
        middle.setFullYear(middle.getFullYear() - 1);
        const formatAllTimeDate = (date) =>
          date.toLocaleDateString("en-US", { month: "short", year: "numeric" });
        return [
          formatAllTimeDate(start),
          formatAllTimeDate(middle),
          formatAllTimeDate(now),
        ];
      }
      const daysBack = rangeKey === "30d" ? 30 : rangeKey === "1y" ? 365 : 6;
      const start = new Date(now);
      start.setDate(start.getDate() - daysBack);
      const middle = new Date(now);
      middle.setDate(middle.getDate() - Math.floor(daysBack / 2));
      return [
        formatAprChartDate(start),
        formatAprChartDate(middle),
        formatAprChartDate(now),
      ];
    };

    const APR_RANGES = {
      "7d": {
        statLabel: "Last 7d avg. APR",
        statValue: "4.12%",
        points: historyAprPoints([4.38, 4.52, 4.18, 4.71, 4.33, 4.42, 4.68]),
      },
      "30d": {
        statLabel: "Last 30d avg. APR",
        statValue: "4.05%",
        points: historyAprPoints([4.28, 4.48, 4.22, 4.62, 4.38, 4.35, 4.62]),
      },
      "1y": {
        statLabel: "Last 1Y avg. APR",
        statValue: "3.89%",
        points: historyAprPoints([4.15, 4.42, 3.92, 4.58, 4.28, 4.15, 4.58]),
      },
      "all-time": {
        statLabel: "All time avg. APR",
        statValue: "3.76%",
        points: historyAprPoints([3.95, 4.35, 3.82, 4.48, 4.12, 4.02, 4.48]),
      },
    };

    const aprCls = (suffix) => `${CLASS_PREFIX}__apr-chart-${suffix}`;

    const renderAprHistoryChart = (chartSvg, rangeKey = "7d") => {
      if (!chartSvg) return;
      const range = APR_RANGES[rangeKey] || APR_RANGES["7d"];
      const { left, right, bottom, yTicks } = APR_CHART_LAYOUT;
      const xLabels = getAprChartDateLabels(rangeKey);
      const points = range.points;
      const gridLines = yTicks
        .map(
          ({ y }) =>
            `<line class="${aprCls("grid-line")}" x1="${left}" y1="${y}" x2="${right}" y2="${y}" />`,
        )
        .join("");
      const yLabels = yTicks
        .map(
          ({ label, y }) =>
            `<text class="${aprCls("label")}" x="0" y="${y + 4}">${label}</text>`,
        )
        .join("");
      const xLabelPositions = [38, 125, 212];
      const xLabelMarkup = xLabels
        .map(
          (label, index) =>
            `<text class="${aprCls("label")}" x="${xLabelPositions[index]}" y="152" text-anchor="middle">${label}</text>`,
        )
        .join("");
      const linePath = `M${points.map(([x, y]) => `${x} ${y}`).join(" L")}`;
      const [endX, endY] = points[points.length - 1];

      chartSvg.innerHTML = `
        ${gridLines}
        <line class="${aprCls("axis-line")}" x1="${left}" y1="${bottom}" x2="${right}" y2="${bottom}" />
        ${yLabels}
        ${xLabelMarkup}
        <path class="${aprCls("line")}" d="${linePath}" />
        <circle class="${aprCls("dot")}" cx="${endX}" cy="${endY}" r="${CHART_DOT_RADIUS}" />
      `;

      return range;
    };

    const STAKING_APR_CHART = {
      left: 50,
      right: SVG_WIDTH,
      bottom: CHART.bottom,
      labelX: 50 - CHART.labelGap,
      xLabelY: 190,
      yTicks: [
        { label: "7%", y: 10 },
        { label: "5%", y: 65 },
        { label: "3%", y: 119 },
        { label: "0%", y: 172 },
      ],
      xLabels: ["1Y ago", "6M ago", "Now"],
      xPositions: [50, 190, 328],
      xrexPoints: stakingAprPoints([
        4.32, 4.58, 4.21, 4.74, 4.41, 4.63, 4.38, 4.72,
      ]),
      bankPoints: [
        [50, aprToStakingY(1.2)],
        [190, aprToStakingY(1.15)],
        [328, aprToStakingY(1.1)],
      ],
    };

    const renderStakingAprChart = (chartSvg) => {
      if (!chartSvg) return;
      const {
        left,
        right,
        bottom,
        labelX,
        xLabelY,
        yTicks,
        xLabels,
        xPositions,
        xrexPoints,
        bankPoints,
      } = STAKING_APR_CHART;
      const gridLines = yTicks
        .map(
          ({ y }) =>
            `<line class="${cls("grid-line")}" x1="${left}" y1="${y}" x2="${right}" y2="${y}" />`,
        )
        .join("");
      const yLabels = yTicks
        .map(
          ({ label, y }) =>
            `<text class="${cls("label")}" x="${labelX}" y="${y + 4}" text-anchor="end">${label}</text>`,
        )
        .join("");
      const xLabelMarkup = xLabels
        .map(
          (label, index) =>
            `<text class="${cls("label")}" x="${xPositions[index]}" y="${xLabelY}" text-anchor="middle">${label}</text>`,
        )
        .join("");
      const toPath = (points) =>
        `M${points.map(([x, y]) => `${x} ${y}`).join(" L")}`;
      const [xrexEndX, xrexEndY] = xrexPoints[xrexPoints.length - 1];
      const [bankEndX, bankEndY] = bankPoints[bankPoints.length - 1];

      chartSvg.innerHTML = `
        ${gridLines}
        <line class="${cls("axis-line")}" x1="${left}" y1="${bottom}" x2="${right}" y2="${bottom}" />
        ${yLabels}
        ${xLabelMarkup}
        <path class="${cls("line")} ${cls("line--bank")}" d="${toPath(bankPoints)}" />
        <path class="${cls("line")} ${cls("line--xrex")}" d="${toPath(xrexPoints)}" />
        <circle class="earn-rewards-learn-page__apr-chart-dot earn-rewards-learn-page__apr-chart-dot--bank" cx="${bankEndX}" cy="${bankEndY}" r="${CHART_DOT_RADIUS}" />
        <circle class="earn-rewards-learn-page__apr-chart-dot" cx="${xrexEndX}" cy="${xrexEndY}" r="${CHART_DOT_RADIUS}" />
      `;
    };

    const positionAprToY = (apr) => {
      const top = 10;
      const bottom = 198;
      return Math.round(bottom - (apr / 6) * (bottom - top));
    };

    const POSITION_YIELD_CHART = {
      left: 53,
      right: 295,
      bottom: 198,
      labelX: 50,
      xLabelY: 213,
      yTicks: [
        { label: "16.00", y: 8 },
        { label: "12.00", y: 55 },
        { label: "8.00", y: 103 },
        { label: "4.00", y: 150 },
        { label: "0.00", y: 182 },
      ],
      xLabels: ["5/5", "5/6", "5/7"],
      xPositions: [53, 152, 255],
      points: [
        [53, 182],
        [105, 130],
        [152, 95],
        [205, 48],
        [255, 10],
      ],
    };

    const POSITION_APR_CHART = {
      left: 52,
      right: 295,
      bottom: 198,
      labelX: 38,
      xLabelY: 211,
      yTicks: [
        { label: "6%", y: 10 },
        { label: "4%", y: 74 },
        { label: "2%", y: 135 },
        { label: "0%", y: 198 },
      ],
      xLabels: ["5/31", "6/5", "6/10", "6/15", "6/20", "6/25"],
      xPositions: [66, 88, 127, 168, 209, 288],
      points: [
        [66, positionAprToY(2.4)],
        [88, positionAprToY(2.1)],
        [127, positionAprToY(2.5)],
        [168, positionAprToY(4.1)],
        [209, positionAprToY(3.6)],
        [288, positionAprToY(5.1)],
      ],
    };

    const renderPositionLineChart = (chartSvg, config) => {
      if (!chartSvg) return;
      const { left, right, bottom, labelX, xLabelY, yTicks, xLabels, xPositions, points } =
        config;
      const gridLines = yTicks
        .map(
          ({ y }) =>
            `<line class="${cls("grid-line")}" x1="${left}" y1="${y}" x2="${right}" y2="${y}" />`,
        )
        .join("");
      const yLabels = yTicks
        .map(
          ({ label, y }) =>
            `<text class="${cls("label")}" x="${labelX}" y="${y + 4}" text-anchor="end">${label}</text>`,
        )
        .join("");
      const xLabelMarkup = xLabels
        .map(
          (label, index) =>
            `<text class="${cls("label")}" x="${xPositions[index]}" y="${xLabelY}" text-anchor="middle">${label}</text>`,
        )
        .join("");
      const linePath = `M${points.map(([x, y]) => `${x} ${y}`).join(" L")}`;
      const [endX, endY] = points[points.length - 1];

      chartSvg.innerHTML = `
        ${gridLines}
        <line class="${cls("axis-line")}" x1="${left}" y1="${bottom}" x2="${right}" y2="${bottom}" />
        ${yLabels}
        ${xLabelMarkup}
        <path class="${cls("line")} ${cls("line--xrex")}" d="${linePath}" />
        <circle class="earn-rewards-learn-page__apr-chart-dot" cx="${endX}" cy="${endY}" r="${CHART_DOT_RADIUS}" />
      `;
    };

    const renderPositionYieldChart = (chartSvg) =>
      renderPositionLineChart(chartSvg, POSITION_YIELD_CHART);

    const renderPositionAprChart = (chartSvg) =>
      renderPositionLineChart(chartSvg, POSITION_APR_CHART);

    return {
      REWARD_RATE,
      MIN_STAKE: 10,
      parseStakeAmount,
      formatLearnReward,
      formatStakingReward,
      calcReward,
      renderChart,
      renderAprHistoryChart,
      renderStakingAprChart,
      renderPositionYieldChart,
      renderPositionAprChart,
      APR_RANGES,
    };
  })();

  const initFinanceEarnPage = () => {
    if (initFinanceEarnPage._inited) return;
    const earnPage = document.querySelector('[data-finance-page="earn"]');
    const nav = earnPage?.querySelector("[data-finance-earn-nav]");
    if (!nav || !earnPage) return;
    initFinanceEarnPage._inited = true;

    const buttons = Array.from(nav.querySelectorAll("[data-finance-earn-section]"));
    const views = Array.from(earnPage.querySelectorAll("[data-finance-earn-view]"));

    const setSection = (sectionId) => {
      buttons.forEach((btn) =>
        btn.classList.toggle(
          "is-active",
          btn.getAttribute("data-finance-earn-section") === sectionId,
        ),
      );
      views.forEach((view) => {
        view.hidden = view.getAttribute("data-finance-earn-view") !== sectionId;
      });
    };

    buttons.forEach((btn) => {
      btn.addEventListener("click", () => {
        const sectionId = btn.getAttribute("data-finance-earn-section");
        if (!sectionId) return;
        setSection(sectionId);
      });
    });

    setSection("products");
  };

  const initEarnRewardsLearnPage = () => {
    if (initEarnRewardsLearnPage._inited) return;
    const learnPage = document.querySelector("[data-earn-rewards-learn-page]");
    if (!learnPage) return;
    initEarnRewardsLearnPage._inited = true;

    const openButtons = document.querySelectorAll("[data-earn-rewards-learn-open]");
    const closeButtons = learnPage.querySelectorAll("[data-earn-rewards-learn-close]");
    const scrollEl = learnPage.querySelector(".earn-rewards-learn-page__scroll");
    const amountInput = learnPage.querySelector("[data-earn-rewards-learn-amount]");
    const amountRow = learnPage.querySelector(".earn-rewards-learn-page__amount-row");
    const rewardEl = learnPage.querySelector("[data-earn-rewards-learn-reward]");
    const chartSvg = learnPage.querySelector("[data-earn-rewards-learn-chart]");
    const aprChartSvg = learnPage.querySelector("[data-earn-rewards-learn-apr-chart]");
    const aprRangeNav = learnPage.querySelector(".earn-rewards-learn-page__apr-range-nav");
    const aprStatLabel = learnPage.querySelector("[data-earn-apr-stat-label]");
    const aprStatValue = learnPage.querySelector("[data-earn-apr-stat-value]");

    const setAprRange = (rangeKey) => {
      const range = earnRewardChart.renderAprHistoryChart(aprChartSvg, rangeKey);
      if (!range) return;
      aprRangeNav
        ?.querySelectorAll("[data-earn-apr-range]")
        .forEach((btn) => {
          const isActive = btn.getAttribute("data-earn-apr-range") === rangeKey;
          btn.classList.toggle("is-active", isActive);
          btn.setAttribute("aria-selected", isActive ? "true" : "false");
        });
      if (aprStatLabel) aprStatLabel.textContent = range.statLabel;
      if (aprStatValue) aprStatValue.textContent = range.statValue;
    };

    const updateEstimator = () => {
      const principal = earnRewardChart.parseStakeAmount(amountInput?.value);
      if (amountInput && document.activeElement !== amountInput && principal > 0) {
        amountInput.value = principal.toLocaleString("en-US", {
          maximumFractionDigits: 2,
        });
      }
      if (rewardEl) {
        rewardEl.textContent = earnRewardChart.formatLearnReward(
          earnRewardChart.calcReward(principal),
        );
      }
      earnRewardChart.renderChart(chartSvg, principal);
    };

    setAprRange("7d");

    aprRangeNav?.querySelectorAll("[data-earn-apr-range]").forEach((btn) => {
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const rangeKey = btn.getAttribute("data-earn-apr-range");
        if (!rangeKey) return;
        setAprRange(rangeKey);
      });
    });

    const close = (opts = {}) => {
      if (opts.instant) {
        learnPage.style.transition = "none";
        learnPage.classList.remove("is-open");
        learnPage.hidden = true;
        requestAnimationFrame(() => {
          learnPage.style.transition = "";
        });
        return;
      }
      learnPage.classList.remove("is-open");
      const onEnd = () => {
        if (!learnPage.classList.contains("is-open")) learnPage.hidden = true;
        learnPage.removeEventListener("transitionend", onEnd);
      };
      learnPage.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 380);
    };

    const open = () => {
      if (amountInput) amountInput.value = "";
      updateEstimator();
      if (scrollEl) scrollEl.scrollTop = 0;
      learnPage.hidden = false;
      requestAnimationFrame(() => learnPage.classList.add("is-open"));
    };

    openButtons.forEach((btn) => {
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        open();
      });
    });
    closeButtons.forEach((btn) => btn.addEventListener("click", () => close()));

    amountInput?.addEventListener("input", updateEstimator);
    amountInput?.addEventListener("blur", () => {
      const principal = earnRewardChart.parseStakeAmount(amountInput.value);
      amountInput.value =
        principal > 0
          ? principal.toLocaleString("en-US", { maximumFractionDigits: 2 })
          : "";
      updateEstimator();
    });

    amountRow?.addEventListener("click", (event) => {
      if (event.target.closest(".earn-rewards-learn-page__currency-pill")) return;
      if (event.target.closest("input")) return;
      amountInput?.focus();
    });

    updateEstimator();
  };

  const EARN_STAKING_FEE = 0;

  const formatEarnStakingUsdt = (value, decimals) =>
    `${value.toLocaleString("en-US", {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    })} USDT`;

  const syncEarnStakingSummaryFields = (root, principal, stakeFee = EARN_STAKING_FEE) => {
    if (!root) return;
    const annualReward = earnRewardChart.calcReward(principal);
    const dailyReward = annualReward / 365;
    const total = principal + stakeFee;
    const set = (selector, text) => {
      const el = root.querySelector(selector);
      if (el) el.textContent = text;
    };
    const heroAmountEl = root.querySelector("[data-earn-staking-summary-hero-amount]");
    if (heroAmountEl) {
      heroAmountEl.textContent = `Allocate ${principal.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      })} USDT`;
    }
    set("[data-earn-staking-summary-annual]", formatEarnStakingUsdt(annualReward, 2));
    set("[data-earn-staking-summary-daily]", formatEarnStakingUsdt(dailyReward, 6));
    set("[data-earn-staking-summary-stake]", formatEarnStakingUsdt(principal, 2));
    set("[data-earn-staking-summary-fee]", formatEarnStakingUsdt(stakeFee, 2));
    set("[data-earn-staking-summary-total]", formatEarnStakingUsdt(total, 2));
  };

  const initEarnStakingPage = () => {
    if (initEarnStakingPage._inited) return;
    const stakingPage = document.querySelector("[data-earn-staking-page]");
    if (!stakingPage) return;
    initEarnStakingPage._inited = true;

    const WALLET_BALANCE = 8032.543241;
    const openButtons = document.querySelectorAll("[data-earn-staking-open]");
    const closeButtons = stakingPage.querySelectorAll("[data-earn-staking-close]");
    const scrollEl = stakingPage.querySelector(".earn-staking-page__scroll");
    const amountInput = stakingPage.querySelector("[data-earn-staking-amount]");
    const amountHintEl = stakingPage.querySelector("[data-earn-staking-amount-hint]");
    const amountRow = stakingPage.querySelector(".earn-staking-page__amount-row");
    const amountErrorEl = stakingPage.querySelector("[data-earn-staking-amount-error]");
    const rewardEl = stakingPage.querySelector("[data-earn-staking-reward]");
    const chartSvg = stakingPage.querySelector("[data-earn-staking-chart]");
    const aprChartSvg = stakingPage.querySelector("[data-earn-staking-apr-chart]");
    const chartModeButtons = Array.from(
      stakingPage.querySelectorAll("[data-earn-staking-chart-mode]"),
    );
    const yieldStat = stakingPage.querySelector('[data-earn-staking-chart-stat="yield"]');
    const aprStat = stakingPage.querySelector('[data-earn-staking-chart-stat="apr"]');
    const yieldPanel = stakingPage.querySelector('[data-earn-staking-chart-panel="yield"]');
    const aprPanel = stakingPage.querySelector('[data-earn-staking-chart-panel="apr"]');
    const yieldDisclaimer = stakingPage.querySelector('[data-earn-staking-disclaimer="yield"]');
    const aprDisclaimer = stakingPage.querySelector('[data-earn-staking-disclaimer="apr"]');
    const nextBtn = stakingPage.querySelector("[data-earn-staking-next]");
    const keyboardNextBtn = document.querySelector("[data-fake-keyboard-earn-next]");
    const pctButtons = Array.from(
      document.querySelectorAll("[data-earn-staking-pct]"),
    );

    const formatInputAmount = (value) =>
      value.toLocaleString("en-US", {
        minimumFractionDigits: 0,
        maximumFractionDigits: 6,
      });

    const PCT_TIERS = [25, 50, 75, 100];
    let selectedPctTier = 0;
    let chartMode = "yield";

    const setChartMode = (mode) => {
      chartMode = mode === "apr" ? "apr" : "yield";
      chartModeButtons.forEach((btn) => {
        const isActive = btn.getAttribute("data-earn-staking-chart-mode") === chartMode;
        btn.classList.toggle("is-active", isActive);
        btn.setAttribute("aria-selected", isActive ? "true" : "false");
      });
      if (yieldStat) yieldStat.hidden = chartMode !== "yield";
      if (aprStat) aprStat.hidden = chartMode !== "apr";
      if (yieldPanel) yieldPanel.hidden = chartMode !== "yield";
      if (aprPanel) aprPanel.hidden = chartMode !== "apr";
      if (yieldDisclaimer) yieldDisclaimer.hidden = chartMode !== "yield";
      if (aprDisclaimer) aprDisclaimer.hidden = chartMode !== "apr";
    };

    const renderActiveChart = (principal) => {
      if (chartMode === "apr") {
        earnRewardChart.renderStakingAprChart(aprChartSvg);
        return;
      }
      earnRewardChart.renderChart(chartSvg, principal);
    };

    const applyPctSelection = () => {
      pctButtons.forEach((btn) => {
        const pct = Number(btn.getAttribute("data-earn-staking-pct"));
        const isActive = selectedPctTier > 0 && pct <= selectedPctTier;
        btn.classList.toggle("is-active", isActive);
        btn.classList.remove("is-active-first", "is-active-last");
      });
      const activeBtns = pctButtons.filter((btn) =>
        btn.classList.contains("is-active"),
      );
      if (activeBtns.length) {
        activeBtns[0].classList.add("is-active-first");
        activeBtns[activeBtns.length - 1].classList.add("is-active-last");
      }
    };

    const isValidStake = (principal) =>
      principal >= earnRewardChart.MIN_STAKE && principal <= WALLET_BALANCE;

    const syncAmountHint = () => {
      if (!amountHintEl || !amountInput) return;
      const principal = earnRewardChart.parseStakeAmount(amountInput.value);
      amountHintEl.hidden = principal > 0;
    };

    const updatePage = () => {
      const principal = earnRewardChart.parseStakeAmount(amountInput?.value);
      const exceedsBalance = principal > WALLET_BALANCE;
      const belowMinimum =
        principal > 0 && principal < earnRewardChart.MIN_STAKE;
      const showAmountError = exceedsBalance || belowMinimum;
      const hasChart = principal > 0;
      const filled = isValidStake(principal);

      stakingPage.classList.toggle("has-chart", hasChart);
      stakingPage.classList.toggle("is-filled", filled);

      if (amountErrorEl) {
        amountErrorEl.classList.toggle("is-visible", showAmountError);
        amountErrorEl.setAttribute(
          "aria-hidden",
          showAmountError ? "false" : "true",
        );
        if (showAmountError) {
          amountErrorEl.textContent = exceedsBalance
            ? "Amount exceeds available balance"
            : "Amount below minimum 10 USDT";
        }
      }
      if (amountInput) {
        amountInput.setAttribute(
          "aria-invalid",
          showAmountError ? "true" : "false",
        );
      }

      syncAmountHint();

      if (rewardEl) {
        rewardEl.textContent = earnRewardChart.formatLearnReward(
          earnRewardChart.calcReward(principal),
        );
      }

      if (nextBtn) nextBtn.disabled = !filled;
      if (keyboardNextBtn) keyboardNextBtn.disabled = !filled;

      renderActiveChart(hasChart ? principal : 0);
      applyPctSelection();
    };

    const close = (opts = {}) => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-earn-hide"));
      if (opts.instant) {
        stakingPage.style.transition = "none";
        stakingPage.classList.remove("is-open");
        stakingPage.hidden = true;
        requestAnimationFrame(() => {
          stakingPage.style.transition = "";
        });
        return;
      }
      stakingPage.classList.remove("is-open");
      const onEnd = () => {
        if (!stakingPage.classList.contains("is-open")) stakingPage.hidden = true;
        stakingPage.removeEventListener("transitionend", onEnd);
      };
      stakingPage.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 380);
    };

    const open = ({ clearInput = false } = {}) => {
      selectedPctTier = 0;
      setChartMode("yield");
      if (clearInput && amountInput) amountInput.value = "";
      if (scrollEl) scrollEl.scrollTop = 0;
      stakingPage.hidden = false;
      requestAnimationFrame(() => {
        stakingPage.classList.add("is-open");
        if (clearInput && amountInput) {
          requestAnimationFrame(() => {
            amountInput.focus({ preventScroll: true });
          });
        }
      });
      updatePage();
    };

    openButtons.forEach((btn) => {
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        open({ clearInput: true });
      });
    });
    closeButtons.forEach((btn) => btn.addEventListener("click", () => close()));

    chartModeButtons.forEach((btn) => {
      btn.addEventListener("click", (event) => {
        event.preventDefault();
        const mode = btn.getAttribute("data-earn-staking-chart-mode");
        if (!mode || mode === chartMode) return;
        setChartMode(mode);
        const principal = earnRewardChart.parseStakeAmount(amountInput?.value);
        if (principal > 0) renderActiveChart(principal);
      });
    });

    amountInput?.addEventListener("focus", () => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-earn-show"));
    });
    amountInput?.addEventListener("input", () => {
      selectedPctTier = 0;
      updatePage();
    });
    amountInput?.addEventListener("blur", () => {
      const principal = earnRewardChart.parseStakeAmount(amountInput.value);
      amountInput.value = principal > 0 ? formatInputAmount(principal) : "";
      if (principal <= 0) selectedPctTier = 0;
      updatePage();
    });

    amountRow?.addEventListener("click", (event) => {
      if (event.target.closest(".earn-staking-page__currency-pill")) return;
      if (event.target.closest("input")) return;
      amountInput?.focus();
      document.dispatchEvent(new CustomEvent("fake-keyboard-earn-show"));
    });

    pctButtons.forEach((btn) => {
      btn.addEventListener("click", () => {
        const pct = Number(btn.getAttribute("data-earn-staking-pct"));
        if (!Number.isFinite(pct) || !amountInput) return;
        if (!PCT_TIERS.includes(pct)) return;
        selectedPctTier = pct;
        const next = (WALLET_BALANCE * pct) / 100;
        amountInput.value = formatInputAmount(next);
        updatePage();
      });
    });

    const summarySheet = document.querySelector("[data-earn-staking-summary-sheet]");
    const summaryPanel = summarySheet?.querySelector(".currency-sheet__panel");
    const summaryOpenBtn = stakingPage.querySelector("[data-earn-staking-summary-open]");

    const syncSummarySheet = () => {
      const principal = earnRewardChart.parseStakeAmount(amountInput?.value);
      syncEarnStakingSummaryFields(summarySheet, principal);
    };

    const closeSummarySheet = () => {
      if (!summarySheet?.classList.contains("is-open")) return;
      summarySheet.classList.remove("is-open");
      const onEnd = () => {
        if (!summarySheet.classList.contains("is-open")) summarySheet.hidden = true;
        summaryPanel?.removeEventListener("transitionend", onEnd);
      };
      summaryPanel?.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 300);
    };

    const openSummarySheet = () => {
      if (!summarySheet) return;
      syncSummarySheet();
      summarySheet.hidden = false;
      requestAnimationFrame(() => summarySheet.classList.add("is-open"));
    };

    summaryOpenBtn?.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openSummarySheet();
    });

    summarySheet
      ?.querySelectorAll("[data-earn-staking-summary-close]")
      .forEach((btn) => btn.addEventListener("click", closeSummarySheet));

    updatePage();
  };

  const initEarnStakingConfirmPage = () => {
    if (initEarnStakingConfirmPage._inited) return;
    const confirmPage = document.querySelector("[data-earn-staking-confirm-page]");
    const amountInput = document.querySelector("[data-earn-staking-amount]");
    const nextBtn = document.querySelector("[data-earn-staking-next]");
    if (!confirmPage || !amountInput || !nextBtn) return;
    initEarnStakingConfirmPage._inited = true;

    const scrollEl = confirmPage.querySelector(".earn-staking-confirm-page__scroll");
    const heroAmountEl = confirmPage.querySelector("[data-earn-staking-confirm-amount]");
    const summaryRoot = confirmPage.querySelector("[data-earn-staking-confirm-summary]");
    const termsToggle = confirmPage.querySelector("[data-earn-staking-confirm-terms-toggle]");
    const termsIcon = confirmPage.querySelector("[data-earn-staking-confirm-terms-icon]");
    const termsBanner = confirmPage.querySelector(".earn-staking-confirm-page__terms");
    const reminderToggle = confirmPage.querySelector("[data-earn-staking-confirm-reminder-toggle]");
    const confirmBtn = confirmPage.querySelector("[data-earn-staking-confirm-submit]");
    const loaderEl = confirmPage.querySelector("[data-earn-staking-confirm-loader]");
    const successPage = document.querySelector("[data-earn-staking-success-page]");
    const successTitleEl = successPage?.querySelector("[data-earn-staking-success-title]");
    const successSubEl = successPage?.querySelector("[data-earn-staking-success-sub]");
    const successDoneBtn = successPage?.querySelector("[data-earn-staking-success-done]");
    const closeButtons = confirmPage.querySelectorAll("[data-earn-staking-confirm-close]");

    const scheduleAllocateEl = confirmPage.querySelector(
      "[data-earn-staking-confirm-schedule-allocate]",
    );
    const scheduleInterestEl = confirmPage.querySelector(
      "[data-earn-staking-confirm-schedule-interest]",
    );
    const schedulePayoutsEl = confirmPage.querySelector(
      "[data-earn-staking-confirm-schedule-payouts]",
    );

    let termsAccepted = false;
    let submitGeneration = 0;
    const SUBMIT_LOADER_MS = 2200;

    const formatSuccessAmountLabel = (principal) => {
      if (!Number.isFinite(principal) || principal <= 0) return "0";
      const rounded = Math.round(principal * 100) / 100;
      return Number.isInteger(rounded)
        ? String(rounded)
        : rounded.toLocaleString("en-US", {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
          });
    };

    const formatFirstYieldSubcopy = () => {
      const firstYield = new Date();
      firstYield.setDate(firstYield.getDate() + 1);
      firstYield.setHours(12, 0, 0, 0);
      const pad = (value) => String(value).padStart(2, "0");
      const dateLabel = `${pad(firstYield.getMonth() + 1)}/${pad(firstYield.getDate())}/${firstYield.getFullYear()}`;
      return `You will receive your first yield in your wallet on ${dateLabel} at 12:00`;
    };

    const syncPortfolioPositionFromStake = (principal) => {
      recordEarnAllocation(principal);
      const stateRoot = document.querySelector(
        '[data-finance-earn-portfolio-state="2"]',
      );
      if (!stateRoot) return;
      const stakeValueEl = stateRoot.querySelector(
        ".finance-earn-portfolio-card__stake-value",
      );
      const totalAmountEl = stateRoot.querySelector(
        ".finance-earn-portfolio__total-amount",
      );
      const formatted = principal.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });
      if (stakeValueEl) stakeValueEl.textContent = formatted;
      if (totalAmountEl) totalAmountEl.textContent = formatted;
    };

    const syncSuccessPage = () => {
      const principal = earnRewardChart.parseStakeAmount(amountInput.value);
      const amountLabel = formatSuccessAmountLabel(principal);
      if (successTitleEl) {
        successTitleEl.textContent = `${amountLabel} USDT successfully allocated to XREX Earn`;
      }
      if (successSubEl) {
        successSubEl.textContent = formatFirstYieldSubcopy();
      }
      syncPortfolioPositionFromStake(principal);
    };

    const dismissEarnFlowOverlays = () => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-earn-hide"));
      [
        "[data-earn-staking-success-page]",
        "[data-earn-staking-confirm-page]",
        "[data-earn-staking-page]",
        "[data-earn-rewards-learn-page]",
      ].forEach((selector) => {
        const el = document.querySelector(selector);
        if (!el) return;
        el.classList.remove("is-open");
        el.hidden = true;
      });
    };

    const openSuccessPage = () => {
      if (!successPage) return;
      syncSuccessPage();
      successPage.hidden = false;
      requestAnimationFrame(() => successPage.classList.add("is-open"));
    };

    const closeSuccessPage = (opts = {}) => {
      if (!successPage) return;
      if (opts.instant) {
        successPage.classList.remove("is-open");
        successPage.hidden = true;
        return;
      }
      successPage.classList.remove("is-open");
      const onEnd = () => {
        if (!successPage.classList.contains("is-open")) successPage.hidden = true;
        successPage.removeEventListener("transitionend", onEnd);
      };
      successPage.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 380);
    };

    const formatScheduleMonthDay = (date) =>
      date.toLocaleDateString("en-US", { month: "short", day: "numeric" });

    const syncScheduleDates = () => {
      const today = new Date();
      const interestStart = new Date(today);
      interestStart.setDate(today.getDate() + 1);
      const payoutsStart = new Date(today);
      payoutsStart.setDate(today.getDate() + 2);

      if (scheduleAllocateEl) {
        scheduleAllocateEl.textContent = `${formatScheduleMonthDay(today)}, today`;
      }
      if (scheduleInterestEl) {
        scheduleInterestEl.textContent = `${formatScheduleMonthDay(interestStart)}, 00:00`;
      }
      if (schedulePayoutsEl) {
        schedulePayoutsEl.textContent = `${formatScheduleMonthDay(payoutsStart)} and onward`;
      }
    };

    const syncConfirmPage = () => {
      const principal = earnRewardChart.parseStakeAmount(amountInput.value);
      if (heroAmountEl) {
        heroAmountEl.textContent = `Allocate ${principal.toLocaleString("en-US", {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        })} USDT`;
      }
      syncEarnStakingSummaryFields(summaryRoot, principal);
      syncScheduleDates();
    };

    const updateConfirmButton = () => {
      if (confirmBtn) confirmBtn.disabled = !termsAccepted;
    };

    const setTermsAccepted = (accepted) => {
      termsAccepted = accepted;
      if (termsToggle) {
        termsToggle.setAttribute("aria-pressed", accepted ? "true" : "false");
      }
      if (termsIcon) {
        termsIcon.src = accepted
          ? "assets/icon_checkbox_on.svg"
          : "assets/icon_checkbox_off.svg";
      }
      updateConfirmButton();
    };

    const toggleTerms = () => {
      setTermsAccepted(!termsAccepted);
    };

    const resetTerms = () => {
      setTermsAccepted(false);
    };

    const closeConfirm = (opts = {}) => {
      submitGeneration += 1;
      if (loaderEl) loaderEl.hidden = true;
      if (opts.instant) {
        confirmPage.style.transition = "none";
        confirmPage.classList.remove("is-open");
        confirmPage.hidden = true;
        requestAnimationFrame(() => {
          confirmPage.style.transition = "";
        });
        return;
      }
      confirmPage.classList.remove("is-open");
      const onEnd = () => {
        if (!confirmPage.classList.contains("is-open")) confirmPage.hidden = true;
        confirmPage.removeEventListener("transitionend", onEnd);
      };
      confirmPage.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 380);
    };

    const resetReminder = () => {
      if (!reminderToggle) return;
      reminderToggle.classList.add("is-expanded");
      reminderToggle.setAttribute("aria-expanded", "true");
    };

    const openConfirm = () => {
      if (nextBtn.disabled) return;
      document.dispatchEvent(new CustomEvent("fake-keyboard-earn-hide"));
      resetTerms();
      resetReminder();
      syncConfirmPage();
      if (scrollEl) scrollEl.scrollTop = 0;
      confirmPage.hidden = false;
      requestAnimationFrame(() => confirmPage.classList.add("is-open"));
    };

    nextBtn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openConfirm();
    });

    closeButtons.forEach((btn) => btn.addEventListener("click", () => closeConfirm()));

    termsToggle?.addEventListener("click", (event) => {
      event.stopPropagation();
      toggleTerms();
    });

    termsBanner?.addEventListener("click", (event) => {
      if (event.target.closest(".earn-staking-confirm-page__terms-link")) return;
      toggleTerms();
    });

    reminderToggle?.addEventListener("click", () => {
      const expanded = reminderToggle.classList.toggle("is-expanded");
      reminderToggle.setAttribute("aria-expanded", expanded ? "true" : "false");
    });

    confirmBtn?.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (confirmBtn.disabled || !termsAccepted) return;
      const gen = (submitGeneration += 1);
      if (loaderEl) loaderEl.hidden = false;
      window.setTimeout(() => {
        if (gen !== submitGeneration) return;
        if (loaderEl) loaderEl.hidden = true;
        setState("visMode", 2, { force: true });
        openSuccessPage();
      }, SUBMIT_LOADER_MS);
    });

    successDoneBtn?.addEventListener("click", () => {
      submitGeneration += 1;
      if (loaderEl) loaderEl.hidden = true;
      dismissEarnFlowOverlays();
      goFinanceEarnPortfolio();
    });
  };

  const initAddSendPanel = () => {
    const panel = document.querySelector("[data-add-send-panel]");
    if (!panel) return { open: () => {}, close: () => {} };

    const titleEl = panel.querySelector("[data-add-send-title]");
    const closeButtons = panel.querySelectorAll("[data-add-send-close]");
    const twdAssetBtn = panel.querySelector('[data-add-send-asset="twd"]');
    const container = document.querySelector(".phone-container");
    let snackbarTimeout = null;

    const syncAddSendRegionUi = () => {
      const isCayman = getPrototypeRegion() === "cayman";
      if (twdAssetBtn) twdAssetBtn.hidden = isCayman;
    };

    const showSnackbar = (message) => {
      const snackbar = container?.querySelector("[data-snackbar]");
      if (!snackbar) return;
      const text = snackbar.querySelector("[data-snackbar-text]");
      if (text) text.textContent = message;
      if (snackbarTimeout) {
        clearTimeout(snackbarTimeout);
        snackbarTimeout = null;
      }
      snackbar.hidden = false;
      snackbar.classList.remove("is-visible");
      void snackbar.offsetWidth;
      requestAnimationFrame(() => snackbar.classList.add("is-visible"));
      snackbarTimeout = setTimeout(() => {
        snackbar.classList.remove("is-visible");
        snackbarTimeout = setTimeout(() => {
          if (!snackbar.classList.contains("is-visible")) snackbar.hidden = true;
        }, 320);
      }, 2200);
    };

    const syncAddSendPanelCopy = (mode = panel.dataset.addSendMode || "add") => {
      const normalizedMode = mode === "send" ? "send" : "add";
      if (titleEl) {
        titleEl.textContent = tr(normalizedMode === "send" ? "Withdraw" : "Deposit");
      }
      panel.setAttribute("aria-label", tr("Deposit or withdraw assets"));
    };

    const setOpen = (nextOpen, mode = "add", opts = {}) => {
      if (nextOpen) {
        const normalizedMode = mode === "send" ? "send" : "add";
        panel.dataset.addSendMode = normalizedMode;
        syncAddSendPanelCopy(normalizedMode);
        panel.hidden = false;
        const scrollBody = panel.querySelector(".add-send-panel__body");
        if (scrollBody) scrollBody.scrollTop = 0;
        requestAnimationFrame(() => panel.classList.add("is-open"));
        return;
      }

      if (!nextOpen) {
        fiatFlowPlaceholderApi?.close?.({ instant: Boolean(opts.instant) });
        const isFiatFlowPanelOpen = (selector) => {
          const el = document.querySelector(selector);
          return Boolean(el?.classList.contains("is-open") && !el.hidden);
        };
        if (
          !isFiatFlowPanelOpen("[data-twd-deposit-setup]") &&
          !isFiatFlowPanelOpen("[data-twd-deposit-select]") &&
          !isFiatFlowPanelOpen("[data-twd-first-time-deposit]") &&
          !isFiatFlowPanelOpen("[data-twd-deposit-instructions]") &&
          !isFiatFlowPanelOpen("[data-twd-deposit-sent-panel]")
        ) {
          twdDepositApi?.clearEntrySource?.();
        }
        if (
          !isFiatFlowPanelOpen("[data-usd-deposit-setup]") &&
          !isFiatFlowPanelOpen("[data-usd-deposit-select]") &&
          !isFiatFlowPanelOpen("[data-cayman-usd-deposit-amount]") &&
          !isFiatFlowPanelOpen("[data-cayman-usd-deposit-instructions]")
        ) {
          usdDepositApi?.clearEntrySource?.();
        }
      }

      if (opts.instant) {
        panel.classList.add("is-instant");
        panel.classList.remove("is-open");
        panel.hidden = true;
        void panel.offsetWidth;
        panel.classList.remove("is-instant");
        return;
      }

      panel.classList.remove("is-open");
      const onEnd = () => {
        if (!panel.classList.contains("is-open")) panel.hidden = true;
        panel.removeEventListener("transitionend", onEnd);
      };
      panel.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 400);
    };

    closeButtons.forEach((btn) => {
      btn.addEventListener("click", () => setOpen(false));
    });

    panel.querySelectorAll("[data-add-send-asset]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const asset = btn.getAttribute("data-add-send-asset");
        if (asset === "twd" && getPrototypeRegion() !== "cayman") {
          const mode = panel.dataset.addSendMode === "send" ? "send" : "add";
          onAddSendTwdSelected(mode);
          return;
        }
        if (asset === "usd" && isUsdFiatFlowRegion()) {
          const mode = panel.dataset.addSendMode === "send" ? "send" : "add";
          onAddSendUsdSelected(mode);
          return;
        }
        showSnackbar("Not in prototype");
      });
    });

    panel.querySelector(".add-send-panel__search")?.addEventListener("click", () => {
      showSnackbar("Not in prototype");
    });

    document.querySelectorAll("[data-open-add-send]").forEach((el) => {
      el.addEventListener("click", () => {
        const mode = el.getAttribute("data-open-add-send") || "add";
        setOpen(true, mode);
      });
    });

    document.addEventListener("prototype-region-change", syncAddSendRegionUi);
    document.addEventListener("prototype-locale-changed", () => {
      if (!panel.classList.contains("is-open")) return;
      syncAddSendPanelCopy();
    });
    syncAddSendRegionUi();

    return {
      open: (mode = "add") => setOpen(true, mode),
      close: (opts) => setOpen(false, "add", opts),
    };
  };

  const getFiatFlowPlaceholderCopy = ({ currency, mode }) => {
    const isDeposit = mode !== "send";
    if (currency === "twd") {
      return isDeposit
        ? {
            title: "Deposit TWD",
            content: "Page : Your XREX TWD deposit account",
            icon: "assets/TWD.svg",
            ariaLabel: "Deposit TWD",
          }
        : {
            title: "Withdraw TWD",
            content: "Page : How much TWD would you like to withdraw",
            icon: "assets/TWD.svg",
            ariaLabel: "Withdraw TWD",
          };
    }
    return isDeposit
      ? {
          title: "Deposit USD",
          content: "Page : Your XREX USD deposit account",
          icon: "assets/USD.svg",
          ariaLabel: "Deposit USD",
        }
      : {
          title: "Withdraw USD",
          content: "Page : How much USD would you like to withdraw",
          icon: "assets/USD.svg",
          ariaLabel: "Withdraw USD",
        };
  };

  const WITHDRAW_PROTOTYPE = {
    twd: {
      avail: 7000,
      maxPerTx: 100000,
      remainingLimit: 200000,
      fee: 150,
    },
    usd: {
      avail: 7000,
      maxPerTx: 100000,
      remainingLimit: 200000,
      fee: 5,
    },
  };

  const WITHDRAW_PROTOTYPE_ACCOUNT_MASK = "••••8999";

  const formatWithdrawDestinationLabel = (bankName) =>
    `${bankName} ${WITHDRAW_PROTOTYPE_ACCOUNT_MASK}`;

  const getWithdrawCustodianName = (currency) => {
    const normalized = currency === "usd" ? "usd" : "twd";
    const custodianKey =
      document.documentElement.dataset[
        normalized === "twd"
          ? "prototypeTwdCustodianActive"
          : "prototypeUsdCustodianActive"
      ] || "kgi-active";
    return tr(
      PROTOTYPE_CUSTODIAN_LABELS[custodianKey] ||
        PROTOTYPE_CUSTODIAN_LABELS["kgi-active"],
    );
  };

  const formatWithdrawAmount = (value) =>
    Number(value).toLocaleString("en-US");

  const formatWithdrawConfirmAmount = (value) =>
    Number(value).toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });

  const PROTOTYPE_XREX_HANDLE = "@SANNEMEIJER123";
  const WITHDRAW_SUCCESS_DELAY_MS = 1250;

  const parseWithdrawAmount = (raw) => {
    const parsed = parseInt(String(raw || "").replace(/[^0-9]/g, ""), 10);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
  };

  const getWithdrawMaxAmount = (config) =>
    Math.max(0, Math.min(config.avail - config.fee, config.maxPerTx));

  const getWithdrawPctAmount = (config, pct) => {
    if (!Number.isFinite(pct) || pct <= 0) return 0;
    const fromBalance = Math.round((config.avail * pct) / 100);
    return Math.min(fromBalance, getWithdrawMaxAmount(config));
  };

  const getWithdrawMinAmount = (config) => config.fee + 1;

  const formatWithdrawRequestedAt = (date = new Date()) => {
    const pad = (value) => String(value).padStart(2, "0");
    return `${pad(date.getDate())}/${pad(date.getMonth() + 1)}/${date.getFullYear()}, ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
  };

  const applyWithdrawAmountInput = (input) => {
    if (!(input instanceof HTMLInputElement)) return 0;
    const parsed = parseWithdrawAmount(input.value);
    input.value = parsed > 0 ? formatWithdrawAmount(parsed) : "";
    return parsed;
  };

  const initFiatFlowPlaceholderPanel = ({ showSnackbar = () => {} } = {}) => {
    const panel = document.querySelector("[data-fiat-flow-placeholder]");
    if (!panel) {
      return { open: () => {}, close: () => {}, isOpen: () => false };
    }

    const titleEl = panel.querySelector("[data-fiat-flow-placeholder-title]");
    const contentEl = panel.querySelector("[data-fiat-flow-placeholder-content]");
    const iconEl = panel.querySelector("[data-fiat-flow-placeholder-icon]");
    const depositView = panel.querySelector("[data-fiat-flow-deposit-view]");
    const withdrawView = panel.querySelector("[data-fiat-flow-withdraw-view]");
    const confirmPanel = panel.querySelector("[data-fiat-withdraw-confirm]");
    const twoFaPanel = panel.querySelector("[data-fiat-withdraw-2fa]");
    const successPanel = panel.querySelector("[data-fiat-withdraw-success]");
    const closeButtons = panel.querySelectorAll(
      "[data-fiat-flow-placeholder-close]",
    );

    const withdrawEls = {
      lead: panel.querySelector("[data-fiat-withdraw-lead]"),
      avail: panel.querySelector("[data-fiat-withdraw-avail]"),
      icon: panel.querySelector("[data-fiat-withdraw-icon]"),
      amount: panel.querySelector("[data-fiat-withdraw-amount]"),
      hint: panel.querySelector("[data-fiat-withdraw-amount-hint]"),
      currency: panel.querySelector("[data-fiat-withdraw-currency]"),
      remainingLimit: panel.querySelector("[data-fiat-withdraw-remaining-limit]"),
      arrival: panel.querySelector("[data-fiat-withdraw-arrival]"),
      fee: panel.querySelector("[data-fiat-withdraw-fee]"),
      receive: panel.querySelector("[data-fiat-withdraw-receive]"),
      continueBtn: panel.querySelector("[data-fiat-withdraw-continue]"),
      amountRow: panel.querySelector(".fiat-withdraw-page__amount-row"),
      amountError: panel.querySelector("[data-fiat-withdraw-amount-error]"),
      maxBtn: panel.querySelector("[data-fiat-withdraw-max]"),
    };

    const confirmEls = {
      title: panel.querySelector("[data-fiat-withdraw-confirm-title]"),
      icon: panel.querySelector("[data-fiat-withdraw-confirm-icon]"),
      amount: panel.querySelector("[data-fiat-withdraw-confirm-amount]"),
      amountSummary: panel.querySelector("[data-fiat-withdraw-confirm-amount-summary]"),
      arrival: panel.querySelector("[data-fiat-withdraw-confirm-arrival]"),
      bankName: panel.querySelector("[data-fiat-withdraw-confirm-bank-name]"),
      accountNumber: panel.querySelector("[data-fiat-withdraw-confirm-account-number]"),
      fromBalance: panel.querySelector("[data-fiat-withdraw-confirm-from-balance]"),
      xrexHandle: panel.querySelector("[data-fiat-withdraw-confirm-xrex-handle]"),
      fee: panel.querySelector("[data-fiat-withdraw-confirm-fee]"),
      total: panel.querySelector("[data-fiat-withdraw-confirm-total]"),
      submit: panel.querySelector("[data-fiat-withdraw-confirm-submit]"),
      labelReceive: panel.querySelector("[data-fiat-withdraw-confirm-label-receive]"),
      labelAmount: panel.querySelector("[data-fiat-withdraw-confirm-label-amount]"),
      labelFee: panel.querySelector("[data-fiat-withdraw-confirm-label-fee]"),
      labelTotal: panel.querySelector("[data-fiat-withdraw-confirm-label-total]"),
      labelFrom: panel.querySelector("[data-fiat-withdraw-confirm-label-from]"),
      labelTo: panel.querySelector("[data-fiat-withdraw-confirm-label-to]"),
    };

    const twoFaEls = {
      title: panel.querySelector("[data-fiat-withdraw-2fa-title]"),
      lead: panel.querySelector("[data-fiat-withdraw-2fa-lead]"),
      helpText: panel.querySelector("[data-fiat-withdraw-2fa-help-text]"),
      labelCode: panel.querySelector("[data-fiat-withdraw-2fa-label-code]"),
      pasteText: panel.querySelector("[data-fiat-withdraw-2fa-paste-text]"),
      code: panel.querySelector("[data-fiat-withdraw-2fa-code]"),
      loader: panel.querySelector("[data-fiat-withdraw-2fa-loader]"),
    };

    const successEls = {
      title: panel.querySelector("[data-fiat-withdraw-success-title]"),
      sub: panel.querySelector("[data-fiat-withdraw-success-sub]"),
      icon: panel.querySelector("[data-fiat-withdraw-success-icon]"),
      amount: panel.querySelector("[data-fiat-withdraw-success-amount]"),
      to: panel.querySelector("[data-fiat-withdraw-success-to]"),
      fee: panel.querySelector("[data-fiat-withdraw-success-fee]"),
      total: panel.querySelector("[data-fiat-withdraw-success-total]"),
      requestedOn: panel.querySelector("[data-fiat-withdraw-success-requested-on]"),
      arrival: panel.querySelector("[data-fiat-withdraw-success-arrival]"),
      status: panel.querySelector("[data-fiat-withdraw-success-status]"),
      custodian: panel.querySelector("[data-fiat-withdraw-success-custodian]"),
      labelTotalWithdrawal: panel.querySelector(
        "[data-fiat-withdraw-success-label-total-withdrawal]",
      ),
      labelTo: panel.querySelector("[data-fiat-withdraw-success-label-to]"),
      labelFee: panel.querySelector("[data-fiat-withdraw-success-label-fee]"),
      labelTotalDeducted: panel.querySelector(
        "[data-fiat-withdraw-success-label-total-deducted]",
      ),
      labelRequested: panel.querySelector(
        "[data-fiat-withdraw-success-label-requested]",
      ),
      labelArrival: panel.querySelector(
        "[data-fiat-withdraw-success-label-arrival]",
      ),
      labelStatus: panel.querySelector("[data-fiat-withdraw-success-label-status]"),
      detailsBtn: panel.querySelector("[data-fiat-withdraw-success-details]"),
      doneBtn: panel.querySelector("[data-fiat-withdraw-success-done]"),
    };

    const WITHDRAW_2FA_PROTOTYPE_CODE = "123456";
    let twoFaSubmitted = false;
    let twoFaSubmitGeneration = 0;
    let twoFaSuccessTimeout = null;

    let withdrawCurrency = "twd";
    let withdrawConfig = WITHDRAW_PROTOTYPE.twd;
    let withdrawBankData = getLinkedBankAccountSheetData("twd");
    let withdrawConfirmAmount = 0;

    const focusWithdrawAmountInput = () => {
      if (withdrawView?.hidden) return;
      const input = withdrawEls.amount;
      if (!(input instanceof HTMLInputElement)) return;
      input.focus();
      const endPos = input.value.length;
      input.setSelectionRange(endPos, endPos);
      document.dispatchEvent(new CustomEvent("fake-keyboard-withdraw-show"));
    };

    const scheduleFocusWithdrawAmountInput = () => {
      const focus = () => focusWithdrawAmountInput();
      panel.addEventListener("transitionend", focus, { once: true });
      window.setTimeout(focus, 360);
    };

    const setSlidePanelOpen = (slidePanel, nextOpen, opts = {}) => {
      if (!slidePanel) return;
      if (nextOpen) {
        slidePanel.hidden = false;
        requestAnimationFrame(() => slidePanel.classList.add("is-open"));
        return;
      }
      if (opts.instant) {
        slidePanel.classList.add("is-instant");
        slidePanel.classList.remove("is-open");
        slidePanel.hidden = true;
        void slidePanel.offsetWidth;
        slidePanel.classList.remove("is-instant");
        return;
      }
      slidePanel.classList.remove("is-open");
      const onEnd = () => {
        if (!slidePanel.classList.contains("is-open")) slidePanel.hidden = true;
        slidePanel.removeEventListener("transitionend", onEnd);
        opts.onClosed?.();
      };
      slidePanel.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 400);
    };

    const syncConfirmUi = () => {
      const curLabel = getBankSheetCurLabel(withdrawCurrency);
      const bankData = withdrawBankData;
      const amountLabel = `${formatWithdrawConfirmAmount(withdrawConfirmAmount)} ${curLabel}`;
      const feeLabel = `${formatWithdrawConfirmAmount(withdrawConfig.fee)} ${curLabel}`;
      const totalLabel = `${formatWithdrawConfirmAmount(
        withdrawConfirmAmount + withdrawConfig.fee,
      )} ${curLabel}`;

      if (confirmEls.title) {
        confirmEls.title.textContent = tr("Confirm withdrawal");
      }
      if (confirmEls.labelReceive) {
        confirmEls.labelReceive.textContent = tr("You will receive");
      }
      if (confirmEls.labelAmount) {
        confirmEls.labelAmount.textContent = tr("Withdrawal amount");
      }
      if (confirmEls.labelFee) {
        confirmEls.labelFee.textContent = tr("Fee (deducted from balance)");
      }
      if (confirmEls.labelTotal) {
        confirmEls.labelTotal.textContent = tr("Total deducted");
      }
      const fromLabel = tr("From");
      const toLabel = tr("To");
      if (confirmEls.labelFrom) confirmEls.labelFrom.textContent = fromLabel;
      if (confirmEls.labelTo) confirmEls.labelTo.textContent = toLabel;
      if (confirmEls.icon) {
        confirmEls.icon.src =
          withdrawCurrency === "usd"
            ? "assets/icon_currency_USD.svg"
            : "assets/icon_currency_TWD.svg";
      }
      if (confirmEls.amount) confirmEls.amount.textContent = amountLabel;
      if (confirmEls.amountSummary) {
        confirmEls.amountSummary.textContent = amountLabel;
      }
      if (confirmEls.arrival) {
        confirmEls.arrival.textContent = tr("Estimated arrival : {time}", {
          time: tr("1–3 business days"),
        });
      }
      if (confirmEls.fromBalance) {
        confirmEls.fromBalance.textContent = tr("XREX · {cur} balance", {
          cur: curLabel,
        });
      }
      if (confirmEls.fee) confirmEls.fee.textContent = feeLabel;
      if (confirmEls.total) confirmEls.total.textContent = totalLabel;
      if (confirmEls.submit) {
        confirmEls.submit.textContent = tr("Withdraw");
      }
      confirmPanel
        ?.querySelectorAll("[data-fiat-withdraw-confirm-back]")
        .forEach((btn) => {
          if (btn.tagName === "BUTTON" && btn.classList.contains("schedule-time-sheet__btn")) {
            btn.textContent = tr("Back");
          }
        });

      const bankName = bankData.bankName;
      if (confirmEls.bankName) confirmEls.bankName.textContent = bankName;
      if (confirmEls.accountNumber) {
        confirmEls.accountNumber.textContent = WITHDRAW_PROTOTYPE_ACCOUNT_MASK;
      }
      if (confirmEls.xrexHandle) {
        confirmEls.xrexHandle.textContent = PROTOTYPE_XREX_HANDLE;
      }
    };

    const syncTwoFaUi = () => {
      if (twoFaEls.title) {
        twoFaEls.title.textContent = tr("Two-factor authentication");
      }
      if (twoFaEls.lead) {
        twoFaEls.lead.textContent = tr(
          "Please enter the 6 digit code from your authenticator app",
        );
      }
      if (twoFaEls.helpText) {
        twoFaEls.helpText.textContent = tr(
          "How to enter your authenticator code?",
        );
      }
      if (twoFaEls.labelCode) {
        twoFaEls.labelCode.textContent = tr("Authentication code");
      }
      if (twoFaEls.pasteText) twoFaEls.pasteText.textContent = tr("Paste");
      if (twoFaEls.code instanceof HTMLInputElement) {
        twoFaEls.code.setAttribute("aria-label", tr("Authentication code"));
      }
    };

    const resetTwoFa = () => {
      twoFaSubmitGeneration += 1;
      if (twoFaSuccessTimeout) {
        clearTimeout(twoFaSuccessTimeout);
        twoFaSuccessTimeout = null;
      }
      twoFaSubmitted = false;
      if (twoFaEls.code instanceof HTMLInputElement) twoFaEls.code.value = "";
      if (twoFaEls.loader) twoFaEls.loader.hidden = true;
    };

    const syncSuccessUi = () => {
      const curLabel = getBankSheetCurLabel(withdrawCurrency);
      const bankData = withdrawBankData;
      const amountLabel = `${formatWithdrawConfirmAmount(withdrawConfirmAmount)} ${curLabel}`;
      const feeLabel = `${formatWithdrawConfirmAmount(withdrawConfig.fee)} ${curLabel}`;
      const totalLabel = `${formatWithdrawConfirmAmount(
        withdrawConfirmAmount + withdrawConfig.fee,
      )} ${curLabel}`;
      const toLabel = formatWithdrawDestinationLabel(bankData.bankName);

      if (successEls.title) {
        successEls.title.textContent = tr("Withdrawal requested");
      }
      if (successEls.sub) {
        successEls.sub.textContent = tr("We'll notify you when it's sent.");
      }
      if (successEls.icon) {
        successEls.icon.src =
          withdrawCurrency === "usd"
            ? "assets/icon_currency_USD.svg"
            : "assets/icon_currency_TWD.svg";
      }
      if (successEls.amount) successEls.amount.textContent = amountLabel;
      if (successEls.to) successEls.to.textContent = toLabel;
      if (successEls.fee) successEls.fee.textContent = feeLabel;
      if (successEls.total) successEls.total.textContent = totalLabel;
      if (successEls.requestedOn) {
        successEls.requestedOn.textContent = formatWithdrawRequestedAt();
      }
      if (successEls.arrival) {
        successEls.arrival.textContent = tr("1–3 business days");
      }
      if (successEls.status) successEls.status.textContent = tr("Processing");
      if (successEls.custodian) {
        successEls.custodian.textContent = tr("Processed via custodian: {name}", {
          name: getWithdrawCustodianName(withdrawCurrency),
        });
      }
      if (successEls.labelTotalWithdrawal) {
        successEls.labelTotalWithdrawal.textContent = tr("Total withdrawal");
      }
      if (successEls.labelTo) successEls.labelTo.textContent = tr("To");
      if (successEls.labelFee) {
        successEls.labelFee.textContent = tr("Fee (deducted from balance)");
      }
      if (successEls.labelTotalDeducted) {
        successEls.labelTotalDeducted.textContent = tr("Total deducted");
      }
      if (successEls.labelRequested) {
        successEls.labelRequested.textContent = tr("Requested on");
      }
      if (successEls.labelArrival) {
        successEls.labelArrival.textContent = tr("Estimated arrival");
      }
      if (successEls.labelStatus) successEls.labelStatus.textContent = tr("Status");
      if (successEls.detailsBtn) {
        successEls.detailsBtn.textContent = tr("View details");
      }
      if (successEls.doneBtn) successEls.doneBtn.textContent = tr("Done");
    };

    const setSuccessOpen = (nextOpen, opts = {}) => {
      if (!successPanel) return;
      if (nextOpen) {
        syncSuccessUi();
        setTwoFaOpen(false, { instant: true });
        setSlidePanelOpen(successPanel, true);
        return;
      }
      setSlidePanelOpen(successPanel, false, opts);
    };

    const returnToWithdrawEntrypoint = () => {
      resetTwoFa();
      setSuccessOpen(false, { instant: true });
      setTwoFaOpen(false, { instant: true });
      setConfirmOpen(false, { instant: true });
      setOpen(false, { instant: true });
      twdDepositApi?.closeAll?.({ instant: true });
      twdDepositApi?.clearEntrySource?.();
      usdDepositApi?.closeAll?.({ instant: true });
      usdDepositApi?.clearEntrySource?.();
      addSendPanelApi?.close?.({ instant: true });
    };

    const submitTwoFaPrototype = () => {
      if (twoFaSubmitted || !twoFaPanel?.classList.contains("is-open")) return;
      twoFaSubmitted = true;
      if (twoFaEls.code instanceof HTMLInputElement) {
        twoFaEls.code.value = WITHDRAW_2FA_PROTOTYPE_CODE;
      }
      if (twoFaEls.loader) twoFaEls.loader.hidden = false;
      const gen = (twoFaSubmitGeneration += 1);
      if (twoFaSuccessTimeout) clearTimeout(twoFaSuccessTimeout);
      twoFaSuccessTimeout = window.setTimeout(() => {
        if (gen !== twoFaSubmitGeneration) return;
        twoFaSuccessTimeout = null;
        if (twoFaEls.loader) twoFaEls.loader.hidden = true;
        setSuccessOpen(true);
      }, WITHDRAW_SUCCESS_DELAY_MS);
    };

    const setTwoFaOpen = (nextOpen, opts = {}) => {
      if (!twoFaPanel) return;
      if (nextOpen) {
        resetTwoFa();
        syncTwoFaUi();
        setSlidePanelOpen(twoFaPanel, true);
        const focusCode = () => twoFaEls.code?.focus();
        twoFaPanel.addEventListener("transitionend", focusCode, { once: true });
        window.setTimeout(focusCode, 360);
        return;
      }
      if (opts.instant) {
        setSlidePanelOpen(twoFaPanel, false, { instant: true });
        resetTwoFa();
        return;
      }
      setSlidePanelOpen(twoFaPanel, false, {
        onClosed: () => resetTwoFa(),
      });
    };

    const setConfirmOpen = (nextOpen, opts = {}) => {
      if (!confirmPanel) return;
      if (nextOpen) {
        hideWithdrawKeyboard();
        setSuccessOpen(false, { instant: true });
        setTwoFaOpen(false, { instant: true });
        syncConfirmUi();
        setSlidePanelOpen(confirmPanel, true);
        return;
      }
      if (opts.instant) {
        setSuccessOpen(false, { instant: true });
        setTwoFaOpen(false, { instant: true });
        setSlidePanelOpen(confirmPanel, false, { instant: true });
        return;
      }
      setSuccessOpen(false, { instant: true });
      setTwoFaOpen(false, { instant: true });
      setSlidePanelOpen(confirmPanel, false, {
        onClosed: () => focusWithdrawAmountInput(),
      });
    };

    const populateDeposit = ({ currency, mode }) => {
      const copy = getFiatFlowPlaceholderCopy({ currency, mode });
      if (titleEl) titleEl.textContent = tr(copy.title);
      if (contentEl) contentEl.textContent = tr(copy.content);
      if (iconEl) iconEl.src = copy.icon;
      panel.setAttribute("aria-label", tr(copy.ariaLabel));
    };

    const syncWithdrawUi = () => {
      const curLabel = getBankSheetCurLabel(withdrawCurrency);
      const bankData = withdrawBankData;

      if (withdrawEls.lead) {
        const destinationMarker = "{{DESTINATION}}";
        const bankName = bankData.bankName;
        const leadText = tr(
          "How much {cur} do you want to withdraw to {destination}?",
          { cur: curLabel, destination: destinationMarker },
        );
        const destinationLabel = formatWithdrawDestinationLabel(bankName);
        const escapedDestination = String(destinationLabel)
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;");
        withdrawEls.lead.innerHTML = leadText.replace(
          destinationMarker,
          `<span class="fiat-withdraw-page__lead-highlight">${escapedDestination}</span>`,
        );
      }
      if (withdrawEls.avail) {
        withdrawEls.avail.textContent = tr("Avail. {amount} {cur}", {
          amount: formatWithdrawConfirmAmount(withdrawConfig.avail),
          cur: curLabel,
        });
      }
      if (withdrawEls.icon) {
        withdrawEls.icon.src =
          withdrawCurrency === "usd"
            ? "assets/icon_currency_USD.svg"
            : "assets/icon_currency_TWD.svg";
      }
      if (withdrawEls.currency) withdrawEls.currency.textContent = curLabel;
      if (withdrawEls.hint) {
        withdrawEls.hint.textContent = tr("Max {max}", {
          max: formatWithdrawAmount(withdrawConfig.maxPerTx),
        });
      }
      if (withdrawEls.remainingLimit) {
        withdrawEls.remainingLimit.textContent = `${formatWithdrawConfirmAmount(
          withdrawConfig.remainingLimit,
        )} ${curLabel}`;
      }

      const labelRemainingLimit = panel.querySelector(
        "[data-fiat-withdraw-label-remaining-limit]",
      );
      const labelArrival = panel.querySelector("[data-fiat-withdraw-label-arrival]");
      const labelFee = panel.querySelector("[data-fiat-withdraw-label-fee]");
      const labelReceive = panel.querySelector("[data-fiat-withdraw-label-receive]");
      const amountLabel = panel.querySelector(
        ".fiat-withdraw-page__amount-section .plan-buffer-funding-input__title",
      );
      if (labelRemainingLimit) {
        labelRemainingLimit.textContent = tr("Remaining limit");
      }
      if (labelArrival) labelArrival.textContent = tr("Estimated arrival");
      if (labelFee) labelFee.textContent = tr("Fee (deducted from balance)");
      if (labelReceive) labelReceive.textContent = tr("You will receive");
      if (amountLabel) amountLabel.textContent = tr("Amount");
      if (withdrawEls.maxBtn) withdrawEls.maxBtn.textContent = tr("Max");

      if (withdrawEls.arrival) {
        withdrawEls.arrival.textContent = tr("1–3 business days");
      }
      if (withdrawEls.fee) {
        withdrawEls.fee.textContent = `${formatWithdrawConfirmAmount(withdrawConfig.fee)} ${curLabel}`;
      }

      const amount = parseWithdrawAmount(withdrawEls.amount?.value);
      const hasAmount = amount > 0;
      const minWithdrawAmount = getWithdrawMinAmount(withdrawConfig);
      const maxWithdrawAmount = getWithdrawMaxAmount(withdrawConfig);
      const belowMinimum = hasAmount && amount < minWithdrawAmount;
      const exceedsBalance = hasAmount && amount > maxWithdrawAmount;
      const exceedsMaxPerTx = hasAmount && amount > withdrawConfig.maxPerTx;
      const showAmountError = belowMinimum || exceedsBalance;

      if (withdrawEls.hint) withdrawEls.hint.hidden = hasAmount;
      if (withdrawEls.amountError) {
        withdrawEls.amountError.textContent = belowMinimum
          ? tr("Minimum amount is {amount} {cur}", {
              amount: formatWithdrawConfirmAmount(minWithdrawAmount),
              cur: curLabel,
            })
          : tr("Exceeds available balance");
        withdrawEls.amountError.classList.toggle("is-visible", showAmountError);
        withdrawEls.amountError.setAttribute(
          "aria-hidden",
          showAmountError ? "false" : "true",
        );
      }
      if (withdrawEls.amount instanceof HTMLInputElement) {
        withdrawEls.amount.setAttribute(
          "aria-invalid",
          showAmountError ? "true" : "false",
        );
      }
      if (withdrawEls.receive) {
        withdrawEls.receive.textContent = hasAmount
          ? `${formatWithdrawConfirmAmount(amount)} ${curLabel}`
          : `- - ${curLabel}`;
      }

      const canContinue =
        hasAmount &&
        !belowMinimum &&
        !exceedsBalance &&
        !exceedsMaxPerTx;
      if (withdrawEls.continueBtn) withdrawEls.continueBtn.disabled = !canContinue;
      const keyboardContinueBtn = document.querySelector(
        "[data-fake-keyboard-withdraw-continue]",
      );
      if (keyboardContinueBtn) {
        keyboardContinueBtn.disabled = !canContinue;
        keyboardContinueBtn.textContent = tr("Continue");
      }
    };

    const populateWithdraw = ({ currency }) => {
      withdrawCurrency = currency === "usd" ? "usd" : "twd";
      withdrawConfig = WITHDRAW_PROTOTYPE[withdrawCurrency];
      withdrawBankData = getLinkedBankAccountSheetData(withdrawCurrency);

      const copy = getFiatFlowPlaceholderCopy({
        currency: withdrawCurrency,
        mode: "send",
      });
      if (titleEl) titleEl.textContent = tr(copy.title);
      if (iconEl) iconEl.src = copy.icon;
      panel.setAttribute("aria-label", tr(copy.ariaLabel));

      if (withdrawEls.amount) withdrawEls.amount.value = "";
      withdrawConfirmAmount = 0;
      setTwoFaOpen(false, { instant: true });
      setConfirmOpen(false, { instant: true });
      syncWithdrawUi();
    };

    const populate = ({ currency, mode }) => {
      const isWithdraw = mode === "send";
      if (depositView) depositView.hidden = isWithdraw;
      if (withdrawView) withdrawView.hidden = !isWithdraw;
      if (isWithdraw) populateWithdraw({ currency });
      else populateDeposit({ currency, mode });
    };

    const hideWithdrawKeyboard = () => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-withdraw-hide"));
    };

    const setOpen = (nextOpen, opts = {}) => {
      if (nextOpen) {
        panel.hidden = false;
        requestAnimationFrame(() => {
          panel.classList.add("is-open");
          if (!withdrawView?.hidden) scheduleFocusWithdrawAmountInput();
        });
        return;
      }
      hideWithdrawKeyboard();
      setTwoFaOpen(false, opts);
      setConfirmOpen(false, opts);
      panel.classList.remove("fiat-flow-placeholder--stacked");
      if (opts.instant) {
        panel.classList.add("is-instant");
        panel.classList.remove("is-open");
        panel.hidden = true;
        void panel.offsetWidth;
        panel.classList.remove("is-instant");
        return;
      }
      panel.classList.remove("is-open");
      const onEnd = () => {
        if (!panel.classList.contains("is-open")) panel.hidden = true;
        panel.removeEventListener("transitionend", onEnd);
      };
      panel.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 400);
    };

    const runAfterPanelOpens = (callback) => {
      if (typeof callback !== "function") return;
      const onEnd = (event) => {
        if (event.target !== panel || event.propertyName !== "transform") return;
        if (!panel.classList.contains("is-open")) return;
        panel.removeEventListener("transitionend", onEnd);
        callback();
      };
      panel.addEventListener("transitionend", onEnd);
      setTimeout(() => {
        panel.removeEventListener("transitionend", onEnd);
        if (panel.classList.contains("is-open")) callback();
      }, 400);
    };

    closeButtons.forEach((btn) => {
      btn.addEventListener("click", () => setOpen(false));
    });
    panel
      .querySelector('[aria-label="Support"]')
      ?.addEventListener("click", () => showSnackbar("Not in prototype"));

    panel
      .querySelector("[data-fiat-withdraw-limit-info]")
      ?.addEventListener("click", () => showSnackbar("Not in prototype"));

    withdrawEls.maxBtn?.addEventListener("click", () => {
      const maxAmount = getWithdrawMaxAmount(withdrawConfig);
      if (!(withdrawEls.amount instanceof HTMLInputElement)) return;
      withdrawEls.amount.value =
        maxAmount > 0 ? formatWithdrawAmount(maxAmount) : "";
      withdrawEls.amount.dispatchEvent(new Event("input", { bubbles: true }));
      withdrawEls.amount.focus();
    });

    withdrawEls.continueBtn?.addEventListener("click", () => {
      if (withdrawEls.continueBtn?.disabled) return;
      withdrawConfirmAmount = parseWithdrawAmount(withdrawEls.amount?.value);
      setConfirmOpen(true);
    });

    confirmPanel?.querySelectorAll("[data-fiat-withdraw-confirm-back]").forEach((btn) => {
      btn.addEventListener("click", () => setConfirmOpen(false));
    });
    confirmPanel
      ?.querySelector('[aria-label="Support"]')
      ?.addEventListener("click", () => showSnackbar("Not in prototype"));
    confirmPanel
      ?.querySelector("[data-fiat-withdraw-confirm-submit]")
      ?.addEventListener("click", () => setTwoFaOpen(true));

    twoFaPanel?.querySelector("[data-fiat-withdraw-2fa-back]")?.addEventListener(
      "click",
      () => setTwoFaOpen(false),
    );
    twoFaPanel
      ?.querySelector('[aria-label="Support"]')
      ?.addEventListener("click", () => showSnackbar("Not in prototype"));
    twoFaPanel
      ?.querySelector("[data-fiat-withdraw-2fa-help]")
      ?.addEventListener("click", () => showSnackbar("Not in prototype"));
    twoFaPanel
      ?.querySelector("[data-fiat-withdraw-2fa-paste]")
      ?.addEventListener("click", (event) => {
        event.stopPropagation();
        submitTwoFaPrototype();
      });
    twoFaPanel?.addEventListener("click", (event) => {
      if (!twoFaPanel.classList.contains("is-open") || twoFaSubmitted) return;
      if (event.target.closest("[data-fiat-withdraw-2fa-back]")) return;
      submitTwoFaPrototype();
    });
    twoFaEls.code?.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        submitTwoFaPrototype();
      }
    });

    successPanel
      ?.querySelector("[data-fiat-withdraw-success-close]")
      ?.addEventListener("click", () => returnToWithdrawEntrypoint());
    successEls.doneBtn?.addEventListener("click", () => returnToWithdrawEntrypoint());
    successEls.detailsBtn?.addEventListener("click", () =>
      showSnackbar("Not in prototype"),
    );

    document.addEventListener("prototype-locale-changed", () => {
      if (!panel.classList.contains("is-open")) return;
      const currency = panel.dataset.fiatFlowCurrency || "twd";
      const mode = panel.dataset.fiatFlowMode || "add";
      populate({ currency, mode });
      if (confirmPanel?.classList.contains("is-open")) syncConfirmUi();
      if (twoFaPanel?.classList.contains("is-open")) syncTwoFaUi();
      if (successPanel?.classList.contains("is-open")) syncSuccessUi();
    });

    withdrawEls.amount?.addEventListener("input", () => {
      applyWithdrawAmountInput(withdrawEls.amount);
      syncWithdrawUi();
      document.dispatchEvent(new CustomEvent("fake-keyboard-withdraw-sync-pct"));
    });
    withdrawEls.amount?.addEventListener("focus", () => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-withdraw-show"));
    });

    withdrawEls.amountRow?.addEventListener("click", (event) => {
      if (event.target.closest("button")) return;
      if (event.target.closest("input")) return;
      withdrawEls.amount?.focus();
      if (withdrawEls.amount instanceof HTMLInputElement) {
        const endPos = withdrawEls.amount.value.length;
        withdrawEls.amount.setSelectionRange(endPos, endPos);
      }
      document.dispatchEvent(new CustomEvent("fake-keyboard-withdraw-show"));
    });

    return {
      open: ({ currency = "twd", mode = "add", stacked = false, onOpened } = {}) => {
        panel.dataset.fiatFlowCurrency = currency;
        panel.dataset.fiatFlowMode = mode;
        panel.classList.toggle("fiat-flow-placeholder--stacked", Boolean(stacked));
        populate({ currency, mode });
        setOpen(true);
        runAfterPanelOpens(onOpened);
      },
      close: (opts) => setOpen(false, opts),
      isOpen: () => Boolean(panel.classList.contains("is-open") && !panel.hidden),
      syncWithdrawUi,
      getWithdrawAmountInput: () => withdrawEls.amount,
      getWithdrawContext: () => ({
        currency: withdrawCurrency,
        config: withdrawConfig,
        amountInput: withdrawEls.amount,
        syncUi: syncWithdrawUi,
        parseAmount: parseWithdrawAmount,
        formatAmount: formatWithdrawAmount,
        applyAmountInput: applyWithdrawAmountInput,
      }),
    };
  };

  const CAYMAN_USD_DEPOSIT_AMOUNT_PROTOTYPE = {
    min: 8,
    max: 300,
    remainingLimit: 17321.41,
    feeRate: 0.0005,
    feeLabel: "0.05%",
  };

  const parseDepositUsdAmount = (raw) => {
    const parsed = parseInt(String(raw || "").replace(/[^0-9]/g, ""), 10);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
  };

  const formatDepositUsdAmount = (value) =>
    Number(value).toLocaleString("en-US");

  const formatDepositUsdConfirmAmount = (value) =>
    Number(value).toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });

  const getDepositUsdPctAmount = (config, pct) => {
    if (!Number.isFinite(pct) || pct <= 0) return 0;
    return Math.round((config.max * pct) / 100);
  };

  const applyDepositUsdAmountInput = (input) => {
    if (!(input instanceof HTMLInputElement)) return 0;
    const parsed = parseDepositUsdAmount(input.value);
    input.value = parsed > 0 ? formatDepositUsdAmount(parsed) : "";
    return parsed;
  };

  const initCaymanUsdDepositAmountPanel = ({ showSnackbar = () => {} } = {}) => {
    const panel = document.querySelector("[data-cayman-usd-deposit-amount]");
    if (!panel) {
      return { open: () => {}, close: () => {}, isOpen: () => false };
    }

    const config = CAYMAN_USD_DEPOSIT_AMOUNT_PROTOTYPE;
    const els = {
      title: panel.querySelector("[data-cayman-usd-deposit-amount-title]"),
      lead: panel.querySelector("[data-cayman-usd-deposit-amount-lead]"),
      icon: panel.querySelector("[data-cayman-usd-deposit-amount-icon]"),
      amount: panel.querySelector("[data-cayman-usd-deposit-amount-input]"),
      hint: panel.querySelector("[data-cayman-usd-deposit-amount-hint]"),
      amountError: panel.querySelector(
        "[data-cayman-usd-deposit-amount-amount-error]",
      ),
      currency: panel.querySelector("[data-cayman-usd-deposit-amount-currency]"),
      remainingLimit: panel.querySelector(
        "[data-cayman-usd-deposit-amount-remaining-limit]",
      ),
      arrival: panel.querySelector("[data-cayman-usd-deposit-amount-arrival]"),
      fee: panel.querySelector("[data-cayman-usd-deposit-amount-fee]"),
      receive: panel.querySelector("[data-cayman-usd-deposit-amount-receive]"),
      confirmBtn: panel.querySelector("[data-cayman-usd-deposit-amount-confirm]"),
      loader: panel.querySelector("[data-cayman-usd-deposit-amount-loader]"),
      amountRow: panel.querySelector(".cayman-usd-deposit-amount__amount-row"),
      labelRemainingLimit: panel.querySelector(
        "[data-cayman-usd-deposit-amount-label-remaining-limit]",
      ),
      labelArrival: panel.querySelector(
        "[data-cayman-usd-deposit-amount-label-arrival]",
      ),
      labelFee: panel.querySelector("[data-cayman-usd-deposit-amount-label-fee]"),
      labelReceive: panel.querySelector(
        "[data-cayman-usd-deposit-amount-label-receive]",
      ),
    };

    const hideDepositKeyboard = () => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-deposit-usd-hide"));
    };

    let submitGeneration = 0;
    const SUBMIT_LOADER_MS = 1600;

    const hideSubmitLoader = () => {
      if (els.loader) els.loader.hidden = true;
    };

    const showSubmitLoader = () => {
      if (els.loader) els.loader.hidden = false;
    };

    const scheduleFocusAmountInput = () => {
      const focusInput = () => els.amount?.focus();
      panel.addEventListener("transitionend", focusInput, { once: true });
      window.setTimeout(focusInput, 360);
    };

    const syncUi = () => {
      const curLabel = "USD";
      if (els.title) els.title.textContent = tr("Deposit USD");
      if (els.lead) {
        els.lead.textContent = tr(
          "How much USD do you want to deposit to XREX?",
        );
      }
      if (els.icon) els.icon.src = "assets/icon_currency_USD.svg";
      if (els.currency) els.currency.textContent = curLabel;
      if (els.hint) {
        els.hint.textContent = tr("Min {min} / Max {max}", {
          min: formatDepositUsdConfirmAmount(config.min),
          max: formatDepositUsdConfirmAmount(config.max),
        });
      }
      if (els.remainingLimit) {
        els.remainingLimit.textContent = `${formatDepositUsdConfirmAmount(
          config.remainingLimit,
        )} ${curLabel}`;
      }
      if (els.labelRemainingLimit) {
        els.labelRemainingLimit.textContent = tr("Remaining limit");
      }
      if (els.labelArrival) {
        els.labelArrival.textContent = tr("Estimated arrival");
      }
      if (els.labelFee) els.labelFee.textContent = tr("Fee");
      if (els.labelReceive) {
        els.labelReceive.textContent = tr("Estimated to receive");
      }
      if (els.arrival) els.arrival.textContent = tr("1–3 business days");
      if (els.fee) els.fee.textContent = config.feeLabel;

      const amountLabel = panel.querySelector(
        ".cayman-usd-deposit-amount__amount-section .plan-buffer-funding-input__title",
      );
      if (amountLabel) amountLabel.textContent = tr("Amount");
      if (els.confirmBtn) els.confirmBtn.textContent = tr("Confirm");

      panel.setAttribute("aria-label", tr("Deposit USD"));

      const amount = parseDepositUsdAmount(els.amount?.value);
      const hasAmount = amount > 0;
      const belowMinimum = hasAmount && amount < config.min;
      const exceedsMaximum = hasAmount && amount > config.max;
      const showAmountError = belowMinimum || exceedsMaximum;

      if (els.hint) els.hint.hidden = hasAmount;
      if (els.amountError) {
        els.amountError.textContent = belowMinimum
          ? tr("Minimum amount is {amount} {cur}", {
              amount: formatDepositUsdConfirmAmount(config.min),
              cur: curLabel,
            })
          : tr("Maximum amount is {amount} {cur}", {
              amount: formatDepositUsdConfirmAmount(config.max),
              cur: curLabel,
            });
        els.amountError.classList.toggle("is-visible", showAmountError);
        els.amountError.setAttribute(
          "aria-hidden",
          showAmountError ? "false" : "true",
        );
      }
      if (els.amount instanceof HTMLInputElement) {
        els.amount.setAttribute(
          "aria-invalid",
          showAmountError ? "true" : "false",
        );
      }
      if (els.receive) {
        if (!hasAmount || belowMinimum || exceedsMaximum) {
          els.receive.textContent = `- - ${curLabel}`;
        } else {
          const receiveAmount = amount * (1 - config.feeRate);
          els.receive.textContent = `${formatDepositUsdConfirmAmount(receiveAmount)} ${curLabel}`;
        }
      }

      const canConfirm =
        hasAmount && !belowMinimum && !exceedsMaximum;
      if (els.confirmBtn) els.confirmBtn.disabled = !canConfirm;

      const keyboardConfirmBtn = document.querySelector(
        "[data-fake-keyboard-deposit-usd-confirm]",
      );
      if (keyboardConfirmBtn) {
        keyboardConfirmBtn.disabled = !canConfirm;
        keyboardConfirmBtn.textContent = tr("Confirm");
      }
    };

    const resetAmount = () => {
      if (els.amount instanceof HTMLInputElement) els.amount.value = "";
      syncUi();
    };

    const setOpen = (nextOpen, opts = {}) => {
      if (nextOpen) {
        resetAmount();
        syncUi();
        panel.hidden = false;
        requestAnimationFrame(() => {
          panel.classList.add("is-open");
          scheduleFocusAmountInput();
        });
        return;
      }
      hideDepositKeyboard();
      hideSubmitLoader();
      submitGeneration += 1;
      if (opts.instant) {
        panel.classList.add("is-instant");
        panel.classList.remove("is-open");
        panel.hidden = true;
        void panel.offsetWidth;
        panel.classList.remove("is-instant");
        return;
      }
      panel.classList.remove("is-open");
      const onEnd = () => {
        if (!panel.classList.contains("is-open")) panel.hidden = true;
        panel.removeEventListener("transitionend", onEnd);
      };
      panel.addEventListener("transitionend", onEnd);
      setTimeout(onEnd, 400);
    };

    const runAfterPanelOpens = (callback) => {
      if (typeof callback !== "function") return;
      const onEnd = (event) => {
        if (event.target !== panel || event.propertyName !== "transform") return;
        if (!panel.classList.contains("is-open")) return;
        panel.removeEventListener("transitionend", onEnd);
        callback();
      };
      panel.addEventListener("transitionend", onEnd);
      setTimeout(() => {
        panel.removeEventListener("transitionend", onEnd);
        if (panel.classList.contains("is-open")) callback();
      }, 400);
    };

    panel
      .querySelector("[data-cayman-usd-deposit-amount-back]")
      ?.addEventListener("click", () => {
        document.dispatchEvent(
          new CustomEvent("cayman-usd-deposit-amount-back"),
        );
      });

    panel
      .querySelector('[aria-label="Support"]')
      ?.addEventListener("click", () => showSnackbar("Not in prototype"));

    panel
      .querySelector("[data-cayman-usd-deposit-amount-limit-info]")
      ?.addEventListener("click", () => showSnackbar("Not in prototype"));

    els.confirmBtn?.addEventListener("click", () => {
      if (els.confirmBtn?.disabled) return;
      hideDepositKeyboard();
      const amount = parseDepositUsdAmount(els.amount?.value);
      if (!amount) return;
      const gen = (submitGeneration += 1);
      showSubmitLoader();
      window.setTimeout(() => {
        if (gen !== submitGeneration) return;
        hideSubmitLoader();
        document.dispatchEvent(
          new CustomEvent("cayman-usd-deposit-amount-confirmed", {
            detail: { amount },
          }),
        );
      }, SUBMIT_LOADER_MS);
    });

    els.amount?.addEventListener("input", () => {
      applyDepositUsdAmountInput(els.amount);
      syncUi();
      document.dispatchEvent(new CustomEvent("fake-keyboard-deposit-usd-sync-pct"));
    });

    els.amount?.addEventListener("focus", () => {
      document.dispatchEvent(new CustomEvent("fake-keyboard-deposit-usd-show"));
    });

    els.amountRow?.addEventListener("click", (event) => {
      if (event.target.closest("button")) return;
      if (event.target.closest("input")) return;
      els.amount?.focus();
      if (els.amount instanceof HTMLInputElement) {
        const endPos = els.amount.value.length;
        els.amount.setSelectionRange(endPos, endPos);
      }
      document.dispatchEvent(new CustomEvent("fake-keyboard-deposit-usd-show"));
    });

    document.addEventListener("prototype-locale-changed", () => {
      if (!panel.classList.contains("is-open") || panel.hidden) return;
      syncUi();
    });

    return {
      open: ({ onOpened } = {}) => {
        setOpen(true);
        runAfterPanelOpens(onOpened);
      },
      close: (opts) => setOpen(false, opts),
      isOpen: () => Boolean(panel.classList.contains("is-open") && !panel.hidden),
      syncUi,
      getDepositContext: () => ({
        config,
        amountInput: els.amount,
        syncUi,
        parseAmount: parseDepositUsdAmount,
        formatAmount: formatDepositUsdAmount,
        applyAmountInput: applyDepositUsdAmountInput,
      }),
    };
  };

