      snackbarTimeout = setTimeout(() => {
        snackbar.classList.remove("is-visible");
        snackbarTimeout = setTimeout(() => {
          if (!snackbar.classList.contains("is-visible")) snackbar.hidden = true;
        }, 320);
      }, 2200);
